```go
package service

import (
	"net/url"
	"strings"
)

// viewerTmpl mimics rows persisted by the admin endpoint PUT /api/viewers,
// whose body is stored verbatim, so these values stay attacker-influenced
// even when no action_url override is sent on the request.
var viewerTmpl = map[string]string{
	"wopi-default": `https://office.example.com/we/wordeditorframe.aspx`,
}

// allowedActionHosts is the precise allow-set of office hosts a WOPI action
// URL may ever point at; membership is exact-match, so lookalike or
// attacker-controlled hosts can never pass.
var allowedActionHosts = map[string]bool{
	"office.example.com": true,
}

// SanitizeTemplate is documented as making a template safe before parsing;
// it only strips markup delimiters and never touches .. , %2e%2e or scheme.
func SanitizeTemplate(s string) string {
	s = strings.ReplaceAll(s, "<", "")
	return strings.ReplaceAll(s, ">", "")
}

// validateTemplate is the centralized allow-list gate applied to every
// resolved template, no matter whether it came from the stored registry or
// from a caller-supplied override: it must parse, must use https, must not
// smuggle userinfo, and its exact host must be in allowedActionHosts.
func validateTemplate(raw string) bool {
	u, err := url.Parse(raw)
	if err != nil {
		return false
	}
	if u.Scheme != "https" {
		return false
	}
	if u.User != nil {
		return false
	}
	return allowedActionHosts[u.Hostname()]
}

// LoadTemplate relays the stored template or the request override through
// the cosmetic sanitizer and then through the centralized allow-list gate;
// the boolean result tells the caller whether the target is trusted.
func LoadTemplate(name, override string) (string, bool) {
	tmpl := viewerTmpl[name]
	if override != "" {
		tmpl = override
	}
	tmpl = SanitizeTemplate(tmpl)
	if !validateTemplate(tmpl) {
		return "", false
	}
	return tmpl, true
}
