```go
package service

import (
	"fmt"
	"net/http"
	"net/url"
)

const wopiSrcPlaceholder = "WOPI_SOURCE"

// isSafeFileID enforces a precise allow-set for the WOPISrc path segment:
// letters, digits, underscore and dash only, 1..128 chars. Dots, slashes,
// percent signs and control characters can never occur, so .. , %2e%2e and
// separator injection are impossible by construction.
func isSafeFileID(id string) bool {
	if len(id) == 0 || len(id) > 128 {
		return false
	}
	for _, c := range id {
		switch {
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		case c >= '0' && c <= '9':
		case c == '_' || c == '-':
		default:
			return false
		}
	}
	return true
}

// OpenEditor assembles the final editor URL and navigates the browser there.
func OpenEditor(w http.ResponseWriter, r *http.Request, viewer, override, fileID string) {
	tmpl, ok := LoadTemplate(viewer, override)
	if !ok {
		http.Error(w, "action url rejected: scheme or host not allowed", http.StatusBadRequest)
		return
	}

	actionURL, err := url.Parse(tmpl)
	if err != nil {
		http.Error(w, fmt.Sprintf("failed to parse action url: %v", err), http.StatusBadRequest)
		return
	}

	// fileID is appended only after the allow-set check above; traversal
	// sequences cannot survive it.
	if !isSafeFileID(fileID) {
		http.Error(w, "invalid file id", http.StatusBadRequest)
		return
	}
	fileSrc := "https://" + r.Host + "/api/wopi/files/" + fileID

	q := actionURL.Query()
	if _, ok := q[wopiSrcPlaceholder]; ok {
		q.Set(wopiSrcPlaceholder, fileSrc)
	} else {
		q.Set("WOPISrc", fileSrc)
	}
	q.Set("lang", "lng")
	actionURL.RawQuery = q.Encode()

	// SINK: navigation target now derives solely from allow-listed templates
	// and a validated file id.
	http.Redirect(w, r, actionURL.String(), http.StatusFound)
}
