// withinBaseFS is the OS-aware containment check used by the driver as a
// second line of defense behind the ops-layer validation.
func withinBaseFS(base, p string) bool {
	absBase, err := filepath.Abs(base)
	if err != nil {
		return false
	}
	absP, err := filepath.Abs(p)
	if err != nil {
		return false
	}
	rel, err := filepath.Rel(absBase, absP)
	if err != nil {
		return false
	}
	return rel == "." || (!strings.HasPrefix(rel, "..") && rel != "")
}

// moveOne performs the physical move with the local storage driver.
// Paths arrive fully resolved from the ops layer; the driver still re-verifies
// containment inside base as defense in depth before touching the filesystem.
func moveOne(_ context.Context, base, srcPath, dstRoot string) error {
	if !withinBaseFS(base, srcPath) || !withinBaseFS(base, dstRoot) {
		return ErrInvalidPath
	}
	target := filepath.Join(dstRoot, filepath.Base(srcPath))
	return os.Rename(srcPath, target)
}
