package storage

import (
	"bytes"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// ContainWithin resolves candidate against root and guarantees the final
// path stays inside root. It is an allow-list containment check (the target
// must land inside root), symlink-aware, not a blacklist of patterns.
func ContainWithin(root, candidate string) (string, error) {
	if candidate == "" {
		return "", errors.New("empty path")
	}
	if filepath.IsAbs(candidate) {
		return "", errors.New("absolute path is not allowed")
	}
	rootAbs, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	target := filepath.Join(rootAbs, candidate)
	sub, err := filepath.Rel(rootAbs, target)
	if err != nil {
		return "", err
	}
	if sub == ".." || strings.HasPrefix(sub, ".."+string(filepath.Separator)) {
		return "", errors.New("path escapes upload root")
	}
	if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
		return "", err
	}
	resolvedRoot, err := filepath.EvalSymlinks(rootAbs)
	if err != nil {
		return "", err
	}
	resolvedDir, err := filepath.EvalSymlinks(filepath.Dir(target))
	if err != nil {
		return "", err
	}
	if resolvedDir != resolvedRoot &&
		!strings.HasPrefix(resolvedDir, resolvedRoot+string(filepath.Separator)) {
		return "", errors.New("resolved path escapes upload root")
	}
	return filepath.Join(resolvedDir, filepath.Base(target)), nil
}

// WriteUpload persists caller-supplied bytes at the caller-chosen path.
// The destination is validated against root before any file is opened.
func WriteUpload(root string, rel string, body []byte) error {
	savepath, err := ContainWithin(root, rel) // centralized containment before the sink
	if err != nil {
		return err
	}
	// #nosec G304
	dst, err := os.OpenFile(savepath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644) // SINK, reached only with contained path
	if err != nil {
		return err
	}
	defer dst.Close()
	_, err = io.Copy(dst, bytes.NewReader(body))
	return err
}

