var (
	ErrInvalidDest    = errors.New("invalid dest parameter")
	ErrInvalidArchive = errors.New("invalid archive parameter")
)

// isSafeSegment 实现白名单精确允许集：仅接受由字母、数字、下划线、连字符
// 组成的 1~64 字符单段名称。允许集在字符层面排除了点、斜杠、反斜杠与空白，
// 因此 ..、../、绝对路径、分隔符注入以及各类编码变形在结构上即不合法，
// 不存在黑名单式绕过空间。
func isSafeSegment(s string) bool {
	if len(s) < 1 || len(s) > 64 {
		return false
	}
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z':
		case r >= 'A' && r <= 'Z':
		case r >= '0' && r <= '9':
		case r == '_' || r == '-':
		default:
			return false
		}
	}
	return true
}

