func listAllMembers(ctx context.Context, f fs.Fs, dir string, out *[]string) error {
	entries, err := f.List(ctx, dir)
	if err != nil {
		return err
	}
	for _, e := range entries {
		*out = append(*out, e.Remote())
		if d, ok := e.(fs.Directory); ok {
			if err := listAllMembers(ctx, f, d.Remote(), out); err != nil {
				return err
			}
		}
	}
	return nil
}
