package service

import (
	"archive/zip"
	"context"
	"errors"
	"os"
	"path"
	"path/filepath"
	"strings"

	_ "github.com/rclone/rclone/backend/local"
	"github.com/rclone/rclone/cmd/archive/extract"
	"github.com/rclone/rclone/fs"
)

const (
	uploadFS    = `:local:/tmp/uploads`  // 用户上传压缩包的存放处
	uploadRoot  = `/tmp/uploads`         // 与 uploadFS 对应的本机路径，供成员名预检使用
	archiveFS   = `:local:/srv/archives` // 解压目标根目录
	archiveRoot = `/srv/archives`        // 与 archiveFS 对应的本机根路径，供包含性校验使用
)

// errEscapeRoot 表示目标路径归一化后逃出了解压根目录。
var errEscapeRoot = errors.New("destination escapes extraction root")

// errUnsafeMember 表示压缩包内存在非规范形式的成员名或符号链接成员。
var errUnsafeMember = errors.New("archive member name is not canonical")

// ensureInsideRoot 是汇聚点前的集中式目录包含性校验：先归一化再验证前缀
// 包含关系，任何 .. 序列、冗余分隔符或绝对路径片段都会在 Clean 后暴露并被
// 拒绝；该判定基于归一化结果而非黑名单，无法通过编码或变形绕过。
func ensureInsideRoot(root, subDir string) error {
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return err
	}
	joined := filepath.Clean(filepath.Join(absRoot, subDir))
	if joined != absRoot && !strings.HasPrefix(joined, absRoot+string(filepath.Separator)) {
		return errEscapeRoot
	}
	return nil
}

// verifyArchiveMembers 在解压前用标准库预检压缩包成员名，阻断成员名层面的
// Zip-Slip：仅接受 Clean 归一化后保持不变的规范相对路径，任何 .. 片段、
// 绝对路径、点片段或冗余分隔符都会改变归一化结果从而被拒绝；符号链接成员
// 一并拒绝，防止先建链接再写穿的两段式逃逸。判定基于归一化等价性而非黑名单。
func verifyArchiveMembers(archiveName string) error {
	reader, err := zip.OpenReader(filepath.Join(uploadRoot, archiveName))
	if err != nil {
		return err
	}
	defer reader.Close()
	for _, f := range reader.File {
		name := strings.TrimSuffix(f.Name, `/`) // 目录条目以尾部斜杠标识，去除后统一检查
		if path.Clean(`/`+name) != `/`+name {
			return errUnsafeMember
		}
		if f.Mode()&os.ModeSymlink != 0 {
			return errUnsafeMember
		}
	}
	return nil
}

// runExtraction 执行真正的解压操作。
// subDir 与 archiveName 在进入汇聚点前经过白名单复核、包含性校验与成员名预检。
func runExtraction(ctx context.Context, archiveName, subDir string) error {
	// 汇聚点集中校验：即使未来出现绕过 ExtractTo 的新调用方，
	// 这里也会再次拦截非法 archiveName 与 subDir。
	if !isSafeSegment(archiveName) {
		return ErrInvalidArchive
	}
	if !isSafeSegment(subDir) {
		return ErrInvalidDest
	}
	if err := ensureInsideRoot(archiveRoot, subDir); err != nil {
		return err
	}
	if err := verifyArchiveMembers(archiveName); err != nil {
		return err
	}
	src, err := fs.NewFs(ctx, uploadFS)
	if err != nil {
		return err
	}
	dst, err := fs.NewFs(ctx, archiveFS)
	if err != nil {
		return err
	}
	// SINK：subDir 已被白名单限定为单段安全名称并通过包含性校验，
	// 成员名经预检均为规范相对路径，写出被约束在 /srv/archives 之内。
	return extract.ArchiveExtract(ctx, src, subDir, dst, archiveName)
}
