<?php
require_once __DIR__ . '/Objects/Comment.php';

class CommentService
{
    // status 字段的精确白名单（允许集），未列出的取值一律拒绝
    private static $allowedStatuses = array('a', 'd', 'spam', 'approved', 'pending');

    // 签发与会话绑定的 CSRF token（管理界面渲染表单时调用）
    public static function getCsrfToken()
    {
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_start();
        }
        if (empty($_SESSION['comments_csrf_token'])) {
            $_SESSION['comments_csrf_token'] = bin2hex(random_bytes(32));
        }
        return $_SESSION['comments_csrf_token'];
    }

    // 集中式 CSRF 校验：token 必须存在于服务端会话且与请求值恒时比对一致
    public static function verifyCsrfToken(array $data)
    {
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_start();
        }
        if (empty($_SESSION['comments_csrf_token']) || empty($data['csrf_token'])) {
            return false;
        }
        return hash_equals($_SESSION['comments_csrf_token'], $data['csrf_token']);
    }

    // 看似有净化：只过滤 title 字段，并丢弃 csrf_token 字段名（不校验其值）
    public static function sanitize(array $data)
    {
        if (isset($data['title'])) {
            $data['title'] = strip_tags($data['title']);
        }
        unset($data['csrf_token']);
        return $data;
    }

    public static function handleSave(array $post)
    {
        // 服务层再次强制 CSRF 校验，覆盖任何绕过 save.php 直接调用本函数的第二入口
        if (!self::verifyCsrfToken($post)) {
            return array('error' => true, 'msg' => 'Invalid CSRF token');
        }
        $clean = self::sanitize($post);
        $o = new Comment(@$clean['id']);
        if (!empty($clean['title'])) {
            $o->setTitle($clean['title']);
        }
        if (!empty($clean['status'])) {
            if (!in_array($clean['status'], self::$allowedStatuses, true)) {
                return array('error' => true, 'msg' => 'Invalid status value');
            }
            $o->setStatus($clean['status']);
        }
        return $o->save() ? array('error' => false, 'msg' => 'Saved')
                          : array('error' => true, 'msg' => 'Save failed');
    }
}
