<?php
namespace App\Services;

use CodeIgniter\HTTP\Files\UploadedFile;
use RuntimeException;

class UploadStorage
{
    public static function persist(UploadedFile $file, ?string $folder, ?string $name): string
    {
        $folder = $folder ?? date('Ymd');
        $name   = $name ?? $file->getClientName();

        // whitelist: folder must be exactly one path segment, charset [A-Za-z0-9_-]
        if (! preg_match('/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/', $folder)) {
            throw new RuntimeException('invalid upload folder');
        }

        // whitelist: name must be exactly one path segment, charset [A-Za-z0-9._-]
        if ($name === '' || $name === '.' || $name === '..'
            || ! preg_match('/^[A-Za-z0-9._-]{1,255}$/', $name)) {
            throw new RuntimeException('invalid upload file name');
        }

        $target = WRITEPATH . 'uploads/' . trim($folder, '/') . '/';

        $file->move($target, $name);

        // defense-in-depth: resolved destination must stay inside the upload root
        $resolved = realpath($target . $name);
        $root     = realpath(WRITEPATH . 'uploads');
        if ($resolved === false || $root === false
            || strpos($resolved, $root . DIRECTORY_SEPARATOR) !== 0) {
            @unlink($target . $name);
            throw new RuntimeException('resolved path escaped upload root');
        }

        return $target . $name;
    }
}
