package service

import (
	"errors"
	"net/url"
	"strings"
)

// viewerTmpl mimics rows persisted by the admin endpoint PUT /api/viewers,
// whose body is stored verbatim, so these values stay attacker-influenced
// even when no action_url override is sent on the request.
var viewerTmpl = map[string]string{
	"wopi-default": `https://office.example.com/we/wordeditorframe.aspx`,
}

// trustedActionHosts is the exact allow-set of hosts a WOPI action URL may
// ever target; membership is a full-string match, so suffix spoofs such as
// office.example.com.evil.com cannot pass.
var trustedActionHosts = map[string]struct{}{
	"office.example.com": {},
}

// ErrUnsafeTemplate reports a template that failed the allow-list check.
var ErrUnsafeTemplate = errors.New("action url template rejected by allow-list")

// ValidateActionURL is the centralized allow-list guard: scheme must be
// https, userinfo must be absent, the port (if any) must be 443, and the
// host must match trustedActionHosts exactly.
func ValidateActionURL(u *url.URL) error {
	if u == nil || u.Scheme != "https" || u.Host == "" {
		return ErrUnsafeTemplate
	}
	if u.User != nil {
		return ErrUnsafeTemplate
	}
	if p := u.Port(); p != "" && p != "443" {
		return ErrUnsafeTemplate
	}
	if _, ok := trustedActionHosts[strings.ToLower(u.Hostname())]; !ok {
		return ErrUnsafeTemplate
	}
	return nil
}

// ValidateTemplate parses raw and applies the same centralized allow-list.
func ValidateTemplate(raw string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return ErrUnsafeTemplate
	}
	return ValidateActionURL(u)
}

// LoadTemplate relays the stored template or the request override through
// the centralized allow-list validation; no value reaches a redirect sink
// without passing ValidateTemplate, whatever its origin.
func LoadTemplate(name, override string) (string, error) {
	tmpl := viewerTmpl[name]
	if override != "" {
		tmpl = override
	}
	if err := ValidateTemplate(tmpl); err != nil {
		return "", err
	}
	return tmpl, nil
}

