package service

import (
	"fmt"
	"net/http"
	"net/url"
	"path"
	"strings"
)

const wopiSrcPlaceholder = "WOPI_SOURCE"

// wopiPathPrefix is the only path prefix a WOPISrc may live under.
const wopiPathPrefix = "/api/wopi/files/"

// SafeFileID enforces an exact character allow-set for file identifiers:
// letters, digits, '-', '_', '.' only, bounded length, and no '..' sequence.
// '/' and '\\' sit outside the allow-set, so separator traversal and
// percent-encoded tricks such as %2e%2e cannot survive this check.
func SafeFileID(id string) bool {
	if id == "" || len(id) > 128 {
		return false
	}
	if strings.Contains(id, "..") {
		return false
	}
	for _, r := range id {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9',
			r == '-', r == '_', r == '.':
		default:
			return false
		}
	}
	return true
}

// OpenEditor assembles the final editor URL and navigates the browser there.
func OpenEditor(w http.ResponseWriter, r *http.Request, viewer, override, fileID string) {
	tmpl, err := LoadTemplate(viewer, override)
	if err != nil {
		http.Error(w, "action url rejected: not on trusted host allow-list", http.StatusBadRequest)
		return
	}

	actionURL, err := url.Parse(tmpl)
	if err != nil {
		http.Error(w, fmt.Sprintf("failed to parse action url: %v", err), http.StatusBadRequest)
		return
	}

	// SINK guard: the same centralized allow-list is re-checked on the parsed
	// URL immediately before navigation, so even a future caller that builds
	// the redirect target directly is still covered here.
	if err := ValidateActionURL(actionURL); err != nil {
		http.Error(w, "action url rejected: not on trusted host allow-list", http.StatusBadRequest)
		return
	}

	if !SafeFileID(fileID) {
		http.Error(w, "invalid file id", http.StatusBadRequest)
		return
	}

	// Containment check: canonicalize the joined path and require it to stay
	// under wopiPathPrefix; together with SafeFileID this blocks ../ escapes.
	joined := path.Join(wopiPathPrefix, fileID)
	if joined == wopiPathPrefix || !strings.HasPrefix(joined, wopiPathPrefix) {
		http.Error(w, "invalid file id", http.StatusBadRequest)
		return
	}

	// fileSrc is built through the url.URL struct so the path component stays
	// canonical and cannot smuggle separators or schemes into the target.
	fileSrc := (&url.URL{Scheme: "https", Host: r.Host, Path: joined}).String()

	q := actionURL.Query()
	if _, ok := q[wopiSrcPlaceholder]; ok {
		q.Set(wopiSrcPlaceholder, fileSrc)
	} else {
		q.Set("WOPISrc", fileSrc)
	}
	q.Set("lang", "lng")
	actionURL.RawQuery = q.Encode()

	// SINK: navigation target now derives only from the allow-listed template
	// plus a contained, canonical WOPISrc value.
	http.Redirect(w, r, actionURL.String(), http.StatusFound)
}

