package storage

import (
	"bytes"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// WriteUpload persists caller-supplied bytes at a caller-chosen relative path
// under the trusted root. Containment is enforced here at the sink, so every
// caller (any route handler or direct construction) is covered centrally.
func WriteUpload(root string, rel string, body []byte) error {
	safe, err := SafeJoin(root, rel) // DEFENSE: canonical containment check before open
	if err != nil {
		return err
	}
	// #nosec G304
	dst, err := os.OpenFile(safe, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644) // SINK
	if err != nil {
		return err
	}
	defer dst.Close()
	_, err = io.Copy(dst, bytes.NewReader(body))
	return err
}

// SafeJoin resolves rel under root and rejects any result escaping root.
// Allowlist-style containment on the canonical path: the cleaned target must
// lie inside root; anything whose location relative to root starts with ..
// is refused. Not a blacklist of patterns.
func SafeJoin(root string, rel string) (string, error) {
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	target := filepath.Join(absRoot, filepath.FromSlash(rel))
	relCheck, err := filepath.Rel(absRoot, target)
	if err != nil {
		return "", err
	}
	if relCheck == ".." || strings.HasPrefix(relCheck, ".."+string(filepath.Separator)) {
		return "", filepath.ErrBadPath
	}
	return target, nil
}

