<?php

namespace App\Monolog;

/**
 * Centralized decoding point for every inbound payload.
 *
 * Allowlist defense (no blacklist, no regex): strict base64 gate,
 * then unserialize() with an EMPTY class allowlist, so remote data
 * can never load a class or fire __wakeup/__destruct gadget chains;
 * any object that still appears (PHP marks it __PHP_Incomplete_Class)
 * is rejected by a recursive type check.
 */
class RecordSanitizer
{
    /**
     * @return mixed scalar or array data only; false on any rejection
     */
    public function decode(string $raw)
    {
        $data = base64_decode(trim($raw), true);
        if (false === $data) {
            return false;
        }
        $value = unserialize($data, ['allowed_classes' => false]);
        if ($this->containsObject($value)) {
            return false;
        }
        return $value;
    }

    private function containsObject($value): bool
    {
        if (is_object($value)) {
            return true;
        }
        if (is_array($value)) {
            foreach ($value as $item) {
                if ($this->containsObject($item)) {
                    return true;
                }
            }
        }
        return false;
    }
}

