        foreach ($server->listen() as $clientId => $line) {
            $record = $sanitizer->decode($line); // SINK: hardened decoder, objects cannot be instantiated
            if (false === $record) {
                continue;
            }
            $output->writeln(sprintf('[client %d] %s', $clientId, print_r($record, true)));
        }
        return 0;
    }
}

