<?php

namespace App\Support;

/**
 * Replaces the legacy class-name blacklist, which was trivially bypassable
 * (PHP class names are case-insensitive and the old block list was incomplete).
 * Performs whitelist validation on already-unserialized data: only scalars,
 * arrays and null are accepted; any object is rejected (fail-closed).
 */
final class PayloadFilter
{
    public static function ensurePlainData(mixed $value): mixed
    {
        if (is_array($value)) {
            foreach ($value as $item) {
                self::ensurePlainData($item);
            }

            return $value;
        }

        if (is_object($value)) {
            throw new \RuntimeException('object payloads are not allowed');
        }

        return $value;
    }
}
