<?php

namespace App\Monolog;

/** Transport-level decoding only; payload safety is enforced at the JSON sink. */
class RecordSanitizer
{
    private const MAX_PAYLOAD_BYTES = 65536;

    public function clean(string $raw): string
    {
        if (strlen($raw) > self::MAX_PAYLOAD_BYTES) {
            return '';
        }
        $data = base64_decode(trim($raw), true);
        if (false === $data) {
            return '';
        }
        return $data;
    }
}

