package jenkins.util;

import java.io.StringReader;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;

/**
 * Whitelist structural validation for imported configuration XML.
 * Replaces the former token-removal blacklist: a deny-list is bypassable by
 * nesting (<<map>> collapses back to <map> after replace) and by case or
 * whitespace variants, so it can never be exhaustive. Only documents whose
 * every element name is in the precise allow-set are accepted.
 */
public final class XmlGuard {

    private static final Set<String> ALLOWED_ELEMENTS =
            new HashSet<>(Arrays.asList("list", "string"));

    private XmlGuard() {
    }

    public static String validateAllowedStructure(String xml) {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        try {
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (ParserConfigurationException e) {
            throw new IllegalArgumentException("parser hardening failed", e);
        }
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);
        Document doc;
        try {
            DocumentBuilder db = dbf.newDocumentBuilder();
            doc = db.parse(new InputSource(new StringReader(xml)));
        } catch (Exception e) {
            throw new IllegalArgumentException("malformed or disallowed xml", e);
        }
        Element root = doc.getDocumentElement();
        if (root == null || !ALLOWED_ELEMENTS.contains(root.getNodeName())) {
            throw new IllegalArgumentException("root element not allowed");
        }
        checkElements(root);
        return xml;
    }

    private static void checkElements(Element parent) {
        NodeList children = parent.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node n = children.item(i);
            if (n.getNodeType() == Node.ELEMENT_NODE) {
                if (!ALLOWED_ELEMENTS.contains(n.getNodeName())) {
                    throw new IllegalArgumentException("element not allowed: " + n.getNodeName());
                }
                checkElements((Element) n);
            }
        }
    }
}
