<?php

namespace App\Support;

/**
 * Hardening layer for unserialization of untrusted payloads.
 *
 * The legacy class-name deny-list was removed on purpose: a name blacklist
 * is always bypassable (PHP class names are case-insensitive, any other
 * loaded gadget class can be abused, and C: custom-serialized tokens never
 * match a name-based str_replace list), so it was never a real defense.
 *
 * The whitelist policy is enforced at the PHP engine level instead:
 * allowed_classes => false is the precise allow-set of instantiable
 * classes, deliberately empty. Every object token (O: or C:) in an
 * untrusted payload degrades to an inert __PHP_Incomplete_Class without
 * running constructors, destructors, __wakeup, __unserialize or any other
 * magic method, which breaks every gadget chain.
 */
final class PayloadFilter
{
    /**
     * Engine-level whitelist: the exact set of classes that unserialize()
     * may instantiate from an untrusted payload — none (false = no class).
     */
    public static function unserializeOptions(): array
    {
        return ['allowed_classes' => false];
    }
}
