package com.example.convert;

import java.io.IOException;
import java.io.InputStream;
import java.io.ObjectInput;
import java.io.ObjectInputFilter;
import java.io.ObjectInputStream;
import com.example.transport.MinaPayloadReceiver;
import org.apache.mina.core.buffer.IoBuffer;

/**
 * Conversion helpers between MINA buffers and object streams.
 */
public final class PayloadConverters {

    private PayloadConverters() {
    }

    /** Pure delegation; adds no validation. */
    public static InputStream toInputStream(IoBuffer buffer) {
        return MinaPayloadReceiver.openRemoteStream(buffer);
    }

    // FIX: centralized whitelist ObjectInputFilter (JEP 290) attached to every
    // ObjectInputStream built from remote bytes; only the exact classes listed
    // below may be deserialized, any other class (gadget chains) is rejected
    // before instantiation, with depth/reference/byte limits enforced.
    private static final ObjectInputFilter REMOTE_FILTER =
            ObjectInputFilter.Config.createFilter(
                    "com.example.protocol.InboundMessage;"
                    + "com.example.protocol.BatchEnvelope;"
                    + "java.lang.String;"
                    + "maxdepth=5;maxrefs=100;maxbytes=1048576");

    // available() check kept only as an early empty-payload rejection;
    // the real guard is the whitelist filter attached below.
    public static ObjectInput toObjectInput(IoBuffer buffer) throws IOException {
        InputStream is = toInputStream(buffer);
        if (is.available() <= 0) {
            throw new IOException("empty payload");
        }
        ObjectInputStream ois = new ObjectInputStream(is);
        ois.setObjectInputFilter(REMOTE_FILTER);
        return ois;
    }
}

