package demo.codec;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputFilter;
import java.io.ObjectInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public final class PayloadCodec {

    private PayloadCodec() {}

    public static byte[] decodeBase64(String raw) {
        return Base64.getDecoder().decode(raw.getBytes(StandardCharsets.ISO_8859_1));
    }

    // Whitelist allow-set (JEP 290): only these exact classes may ever be deserialized;
    // the trailing !* rejects every other class, so no gadget package can pass.
    private static final ObjectInputFilter SAFE_FILTER =
            ObjectInputFilter.Config.createFilter(
                    "maxbytes=65536;maxdepth=32;maxrefs=1000;"
                            + "demo.bean.*;java.lang.String;java.lang.Boolean;"
                            + "java.lang.Integer;java.lang.Long;java.lang.Double;"
                            + "java.util.ArrayList;java.util.HashMap;!*");

    /** SINK: native deserialization, now guarded by the strict allowlist filter. */
    public static Object deserialize(byte[] bytes) throws IOException, ClassNotFoundException {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            in.setObjectInputFilter(SAFE_FILTER);   // centralized allowlist defense installed at the sink
            return in.readObject();                 // every class in the stream is checked before instantiation
        }
    }

    public static Object decodeAndDeserialize(String raw) throws Exception {
        byte[] bytes = decodeBase64(raw);
        return deserialize(bytes);
    }
}

