package org.apache.camel.component.infinispan.remote.protostream;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InvalidClassException;
import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;

import org.apache.camel.support.DefaultExchangeHolder;
import org.apache.camel.util.ClassLoadingAwareObjectInputStream;

/** Marshalling helpers for {@link DefaultExchangeHolder} over Protostream transports. */
final class DefaultExchangeHolderUtils {

    /**
     * Exact allow-set of classes that may be materialised from untrusted
     * cache payloads. Anything outside this set is rejected before it can be
     * loaded or instantiated, which blocks known deserialization gadgets.
     */
    private static final Set<String> ALLOWED_CLASSES = new HashSet<>(Arrays.asList(
            DefaultExchangeHolder.class.getName(),
            String.class.getName(),
            Byte.class.getName(),
            Short.class.getName(),
            Integer.class.getName(),
            Long.class.getName(),
            Float.class.getName(),
            Double.class.getName(),
            Boolean.class.getName(),
            Character.class.getName(),
            byte[].class.getName(),
            HashMap.class.getName(),
            ArrayList.class.getName(),
            Date.class.getName(),
            BigDecimal.class.getName(),
            BigInteger.class.getName()));

    private DefaultExchangeHolderUtils() {
    }

    public static DefaultExchangeHolder deserialize(byte[] bytes) throws IOException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ClassWhitelistObjectInputStream(bais)) {
            return (DefaultExchangeHolder) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new IOException(e);
        }
    }

    /**
     * Look-ahead stream enforcing the exact allow-set during resolveClass and
     * resolveProxyClass, so gadget classes are never loaded or instantiated.
     */
    private static final class ClassWhitelistObjectInputStream extends ClassLoadingAwareObjectInputStream {

        private ClassWhitelistObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            String name = desc.getName();
            if (name.startsWith("[")) {
                requireAllowedArray(name);
            } else if (!ALLOWED_CLASSES.contains(name)) {
                throw new InvalidClassException("Class outside deserialization allow-set: " + name);
            }
            return super.resolveClass(desc);
        }

        @Override
        protected Class<?> resolveProxyClass(String[] interfaces) throws IOException, ClassNotFoundException {
            for (String itf : interfaces) {
                if (!ALLOWED_CLASSES.contains(itf)) {
                    throw new InvalidClassException("Proxy interface outside allow-set: " + itf);
                }
            }
            return super.resolveProxyClass(interfaces);
        }

        private static void requireAllowedArray(String descriptor) throws InvalidClassException {
            String component = descriptor;
            while (component.startsWith("[")) {
                component = component.substring(1);
            }
            if (component.startsWith("L") && component.endsWith(";")) {
                component = component.substring(1, component.length() - 1);
                if (!ALLOWED_CLASSES.contains(component)) {
                    throw new InvalidClassException("Array component outside allow-set: " + component);
                }
            } else if (!isPrimitiveDescriptor(component)) {
                throw new InvalidClassException("Array component outside allow-set: " + component);
            }
        }

        private static boolean isPrimitiveDescriptor(String descriptor) {
            return descriptor.length() == 1 && "BCDFIJSZ".indexOf(descriptor.charAt(0)) >= 0;
        }
    }
}

