package org.example.mail;

import java.io.ByteArrayInputStream;
import java.io.ObjectInputFilter;
import java.io.ObjectInputStream;
import java.util.Arrays;
import java.util.Base64;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.mail.internet.MimeMessage;

/**
 * Turns base64 header values back into live java objects for downstream
 * processors; only headers that survived the strict allow-set filter reach
 * this path, and deserialization itself is guarded by a JEP-290 class
 * allow-list so no untrusted type can ever be materialized.
 */
public class MailPayloadDecoder {

    /**
     * Exact allow-set of harmless value classes that may be materialized
     * from a serialized payload; nothing outside this set is ever created.
     */
    private static final Set<Class<?>> ALLOWED_DESERIALIZATION_TYPES =
            new HashSet<>(Arrays.asList(
                    String.class, Boolean.class, Character.class,
                    Byte.class, Short.class, Integer.class, Long.class,
                    Float.class, Double.class,
                    java.math.BigInteger.class, java.math.BigDecimal.class,
                    java.util.Date.class, java.util.UUID.class));

    /**
     * JEP-290 sink guard: rejects every class outside the allow-set before
     * its constructor or readObject can run.
     */
    private static final ObjectInputFilter SAFE_DESERIALIZATION_FILTER = info -> {
        Class<?> serialClass = info.serialClass();
        if (serialClass == null) {
            return ObjectInputFilter.Status.UNDECIDED; // primitives and null refs
        }
        return ALLOWED_DESERIALIZATION_TYPES.contains(serialClass)
                ? ObjectInputFilter.Status.ALLOWED
                : ObjectInputFilter.Status.REJECTED;
    };

    public Object consume(MimeMessage message) throws Exception {
        Map<String, Object> raw = new MailMessageAdapter().extractHeaders(message);
        Map<String, Object> filtered = new MailHeaderFilterStrategy().apply(raw);
        return decode(filtered, "x-java-object");
    }

    public Object decode(Map<String, Object> headers, String field)
            throws Exception {
        Object raw = headers.get(field);
        if (raw == null) {
            return null;
        }
        byte[] bytes = Base64.getDecoder().decode(raw.toString());
        try (ObjectInputStream ois =
                new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            ois.setObjectInputFilter(SAFE_DESERIALIZATION_FILTER); // allow-list sink guard
            return ois.readObject();                         // SINK (guarded)
        }
    }
}
