package org.example.mail;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.apache.camel.support.DefaultHeaderFilterStrategy;

/**
 * Upstream policy: only a precise allow-set of well-known, benign mail
 * header names may pass downstream; every other name (including any
 * serialized-payload header such as x-java-object) is dropped. There is
 * no wildcard, no prefix rule and no blacklist left to bypass.
 */
public class MailHeaderFilterStrategy extends DefaultHeaderFilterStrategy {

    /**
     * Exact allow-set of benign RFC-5322 style header names; untrusted
     * header values can only travel downstream under one of these names.
     */
    private static final Set<String> ALLOWED_HEADERS = new HashSet<>(Arrays.asList(
            "from", "to", "cc", "bcc", "reply-to", "subject", "date",
            "message-id", "in-reply-to", "references", "content-type",
            "content-transfer-encoding", "mime-version", "received",
            "return-path", "x-priority"));

    public MailHeaderFilterStrategy() {
        initialize();
    }

    protected void initialize() {
        setLowerCase(true);
        // filter headers begin with "Camel" or "org.apache.camel"
        setOutFilterStartsWith(CAMEL_FILTER_STARTS_WITH);
    }

    public Map<String, Object> apply(Map<String, Object> headers) {
        Map<String, Object> out = new HashMap<>();
        for (Map.Entry<String, Object> e : headers.entrySet()) {
            String name = e.getKey().toLowerCase();
            if (ALLOWED_HEADERS.contains(name)) {            // whitelist exact match
                out.put(name, e.getValue());                 // only benign names pass
            }
        }
        return out;
    }
}
