import java.util.HashSet;
import java.util.Set;

public class PreprocessingService {

    // 防御: 白名单精确允许集, 仅放行模板预处理必需的固定 entry 名, 取代可绕过的后缀黑名单与字节扫描
    private static final Set<String> ALLOWED_ENTRIES = new HashSet<>(Arrays.asList(
            "word/document.xml",
            "word/header1.xml",
            "word/header2.xml",
            "word/footer1.xml",
            "word/footer2.xml",
            "word/footnotes.xml",
            "word/endnotes.xml",
            "content.xml",
            "styles.xml"));

    private boolean isAllowedEntry(String entryName) {
        return entryName != null && ALLOWED_ENTRIES.contains(entryName);
    }

    public String preprocessEntry(XDocArchive archive, String entryName) throws Exception {
        if (!isAllowedEntry(entryName)) {
            throw new IllegalArgumentException("blocked entry");
        }
        InputStream entryStream = archive.getEntryInputStream(entryName); // 污点透传
        StringWriter out = new StringWriter();
        new SAXXDocPreprocessor().preprocess(entryName, entryStream, out, null, null, null);
        return out.toString();
    }
}
