package demo.exec;
import java.util.Map;
import com.fasterxml.jackson.databind.ObjectMapper;
import demo.graphql.GraphQlRequest;

/** Executes a request; binds client JSON only to safe core types, never to polymorphic subtypes. */
public class RequestExecutionService {

	// CWE-502 fix: default typing is NOT activated, so no '@class' property can
	// trigger class loading or instantiation; untrusted JSON is bound only to the
	// closed safe set (LinkedHashMap, ArrayList, String, Number, Boolean, null)
	private final ObjectMapper mapper = new ObjectMapper();

	public Map<String, Object> execute(GraphQlRequest request) {
		try {
			String rawVars = mapper.writeValueAsString(request.getVariables());
			Object typedVars = mapper.readValue(rawVars, Object.class); // hardened: core types only
			String rawExt = mapper.writeValueAsString(request.getExtensions());
			mapper.readValue(rawExt, Object.class); // hardened: same safe mapper
			return Map.of("ok", String.valueOf(typedVars));
		}
		catch (Exception ex) {
			throw new IllegalStateException("execution failed", ex);
		}
	}
}

