namespace App\Parser;

use DOMDocument;
use DOMXPath;

/**
 * Minimal MathML walker. External DTDs and entities are never resolved:
 * the parse sink itself refuses all external resources, so no upstream
 * string rewriting is trusted for entity safety.
 */
