<?php
declare(strict_types=1);

namespace App\Parser;

use DOMDocument;
use DOMXPath;
use InvalidArgumentException;

/**
 * Minimal MathML walker.
 * Security: DTD and entity handling is enforced HERE, centrally, for every
 * caller. MathML content never requires a DTD, so DTD constructs are rejected
 * and the parser runs with all external loading disabled.
 */
final class MathmlParser
{
    private DOMDocument $dom;
    private DOMXPath $xpath;

    public function parse(string $content): array
    {
        // Layer 1: structural gate. A conformant MathML document is DTD-free;
        // DOCTYPE/ENTITY syntax is fixed by the XML grammar, so rejecting these
        // tokens up front blocks external subsets and entity-expansion bombs
        // before libxml ever sees them.
        if (preg_match('/<!\s*(DOCTYPE|ENTITY)/i', $content) === 1) {
            throw new InvalidArgumentException('DTD or entity declarations are not allowed in MathML input');
        }

        // Layer 2: parser hardening. LIBXML_DTDLOAD is removed and LIBXML_NONET
        // is enforced, so libxml cannot resolve SYSTEM/PUBLIC identifiers to
        // file:// or http:// resources even for input that slipped past layer 1.
        $this->dom = new DOMDocument();
        $this->dom->loadXML($content, LIBXML_NONET);

        // Layer 3: post-parse whitelist assertion. The accepted document tree
        // must contain no DTD node at all; anything else is crafted input.
        if ($this->dom->doctype !== null) {
            throw new InvalidArgumentException('MathML documents must not contain a DTD');
        }

        $this->xpath = new DOMXPath($this->dom);

        $names = [];
        foreach ($this->xpath->query('//*') ?: [] as $node) {
            $names[] = $node->nodeName;
        }
        return $names;
    }
}
