<?php
declare(strict_types=1);

namespace App\Security;

// Deep structural inspection: strict element/attribute whitelist over a safely parsed DOM.
class SvgDomScanner
{
    // Exact allow-set of SVG elements permitted in user uploads.
    // Deliberately excludes script, use, foreignObject, a, image, handler, animate*, set, style.
    private const ALLOWED_ELEMENTS = [
        'svg', 'title', 'desc', 'metadata', 'defs', 'g', 'symbol',
        'path', 'rect', 'circle', 'ellipse', 'line', 'polyline', 'polygon',
        'text', 'tspan', 'textPath', 'marker', 'clipPath', 'mask',
        'linearGradient', 'radialGradient', 'pattern', 'stop',
        'filter', 'feGaussianBlur', 'feOffset', 'feBlend', 'feColorMatrix',
        'feComposite', 'feFlood', 'feMerge', 'feMergeNode',
    ];

    // Exact allow-set of attributes; on* handlers can never match, href-style attrs governed by URL policy.
    private const ALLOWED_ATTRIBUTES = [
        'id', 'class', 'd', 'x', 'y', 'x1', 'y1', 'x2', 'y2', 'cx', 'cy', 'r',
        'rx', 'ry', 'width', 'height', 'points', 'fill', 'stroke',
        'stroke-width', 'stroke-linecap', 'stroke-linejoin', 'opacity',
        'fill-opacity', 'stroke-opacity', 'transform', 'viewBox',
        'preserveAspectRatio', 'xmlns', 'xmlns:xlink', 'offset',
        'stop-color', 'stop-opacity', 'gradientUnits', 'gradientTransform',
        'patternUnits', 'fx', 'fy', 'font-family', 'font-size',
        'font-weight', 'text-anchor', 'clip-path', 'mask', 'filter',
        'version', 'href', 'xlink:href',
    ];

    // URL-bearing attributes must pass the same-document fragment policy.
    private const URL_ATTRIBUTES = ['href', 'xlink:href', 'src'];

    public function scan(string $svg): array
    {
        // Defense 1: reject DTD/entity constructs in raw bytes before any parsing (XXE kill-switch).
        if (1 === preg_match('/<!DOCTYPE|<!ENTITY/i', $svg)) {
            return ['dtd-or-entity-declared'];
        }

        \libxml_use_internal_errors(true);
        $dom = new \DOMDocument();
        // Defense 2: safe parser flags — LIBXML_NOENT and LIBXML_DTDLOAD removed; LIBXML_NONET blocks network fetches.
        $dom->loadXML($svg, \LIBXML_NONET);
        $errors = \libxml_get_errors();
        \libxml_clear_errors();
        if ([] !== $errors || null === $dom->documentElement) {
            return ['xml-malformed'];
        }

        $findings = [];

        // Defense 3: element whitelist — anything not explicitly allowed becomes a finding.
        foreach ($dom->getElementsByTagName('*') as $node) {
            $name = '' !== $node->localName ? $node->localName : $node->nodeName;
            if (!\in_array($name, self::ALLOWED_ELEMENTS, true)) {
                $findings[] = 'element:' . $name;
            }
            // Defense 4: attribute whitelist; on* handlers are explicitly rejected first.
            foreach ($node->attributes as $attr) {
                $attrName = '' !== $attr->localName ? $attr->localName : $attr->nodeName;
                $attrKey = ('' !== $attr->prefix ? $attr->prefix . ':' : '') . $attrName;
                if (0 === \stripos($attrName, 'on')) {
                    $findings[] = 'attribute:on*:' . $attrKey;
                    continue;
                }
                if (!\in_array($attrKey, self::ALLOWED_ATTRIBUTES, true) && !\in_array($attrName, self::ALLOWED_ATTRIBUTES, true)) {
                    $findings[] = 'attribute:' . $attrKey;
                    continue;
                }
                // Defense 5: URL attributes restricted to same-document fragment references.
                if (\in_array($attrName, self::URL_ATTRIBUTES, true) && !$this->isSameDocumentRef($attr->nodeValue ?? '')) {
                    $findings[] = 'url:' . $attrKey;
                }
            }
        }

        return $findings;
    }

    private function isSameDocumentRef(string $url): bool
    {
        $trimmed = trim($url);
        return '' !== $trimmed && '#' === $trimmed[0];
    }
}

