<?php
declare(strict_types=1);

namespace Saml;

use DOMDocument;

final class XmlSanitizer
{
    /**
     * Precise whitelist: only known SAML protocol message roots are accepted.
     * Replaces the old case-sensitive strpos blacklist, which differently
     * cased or differently encoded DTD payloads could slip past. Entity and
     * DOCTYPE handling is independently disabled in DOMDocumentFactory, so
     * this gate is a second layer, never the sole defense.
     */
    private const ALLOWED_ROOTS = [
        'response',
        'authnrequest',
        'logoutrequest',
        'logoutresponse',
        'artifactresolve',
        'artifactresponse',
    ];

    public static function isAllowedRoot(DOMDocument $doc): bool
    {
        $root = $doc->documentElement;
        if ($root === null) {
            return false;
        }
        $name = strtolower($root->localName ?? $root->nodeName);
        return in_array($name, self::ALLOWED_ROOTS, true);
    }
}
# === file: src/Saml/DOMDocumentFactory.php ===
<?php
declare(strict_types=1);

namespace Saml;

use DOMDocument;
use RuntimeException;

final class DOMDocumentFactory
{
    public static function fromString(string $xml): DOMDocument
    {
        if (trim($xml) === '') {
            throw new RuntimeException('empty payload');
        }
        $dom = new DOMDocument('1.0', 'UTF-8');
        $dom->resolveExternals = false;      // never fetch external DTD parts or entities
        $dom->substituteEntities = false;    // never expand entities, internal or external
        $options = LIBXML_NONET;             // DTDLOAD|DTDATTR|PARSEHUGE removed: no DTD processing at all
        $loaded = $dom->loadXML($xml, $options);
        if (!$loaded) {
            throw new RuntimeException('unparseable xml');
        }
        foreach ($dom->childNodes as $child) {   // defense in depth: DTD-bearing docs rejected before use
            if ($child->nodeType === XML_DOCUMENT_TYPE_NODE) {
                throw new RuntimeException('doctype forbidden');
            }
        }
        return $dom;
    }

    public static function fromFile(string $file): DOMDocument
    {
        $data = @file_get_contents($file);
        if ($data === false || trim($data) === '') {
            throw new RuntimeException('bad file');
        }
        return self::fromString($data);
    }
}

