package com.grid.xml;

import java.io.Reader;
import java.io.StringReader;
import java.util.Locale;

/**
 * DEFENSE (layer 2): strict fail-closed validator for CGMES imports.
 * The old strip-based blacklist was bypassable (nested keywords such as
 * <<!DOCTYPE!DOCTYPE survive String.replace), so nothing is stripped here:
 * the whole request is rejected when any DTD-related construct appears,
 * matched case-insensitively. The authoritative control is the hardened
 * XMLInputFactory in FullModelParser.
 */
public final class XmlSanitizer {

    private XmlSanitizer() {
    }

    public static Reader validateNoDtd(String xml) {
        String probe = xml.toLowerCase(Locale.ROOT);
        if (probe.contains("<!doctype") || probe.contains("<!entity")
                || probe.contains("<!attlist") || probe.contains("<!notation")) {
            throw new IllegalArgumentException(
                    "DTD or entity declarations are forbidden in CGMES documents");
        }
        return new StringReader(xml);
    }
}
# === file: src/main/java/com/grid/cgmes/FullModelParser.java ===
package com.grid.cgmes;

import javax.xml.XMLConstants;
import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamReader;
import java.io.Reader;

public final class FullModelParser {

    public record FullModel(String id, int version) {
        @Override
        public String toString() {
            return id + ':' + version;
        }
    }

    // DEFENSE (layer 1, centralized): hardening at the factory level applies to
    // every caller of parse(), so both controller routes and any direct call
    // site are covered by the same guard.
    private static XMLInputFactory newFactory() {
        XMLInputFactory f = XMLInputFactory.newInstance();
        f.setProperty(XMLConstants.SUPPORT_DTD, false);
        f.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);
        f.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        f.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
        return f;
    }

    // SINK: entity resolution happens while this reader advances
    public static FullModel parse(Reader reader) {
        try {
            XMLStreamReader r = newFactory().createXMLStreamReader(reader);
            r.nextTag();
            String id = r.getAttributeValue(null, "about");
            while (r.hasNext()) {
                if (r.next() == XMLStreamReader.START_ELEMENT
                        && r.getLocalName().equals("version")) {
                    return new FullModel(id, Integer.parseInt(r.getElementText()));
                }
            }
            return new FullModel(id, -1);
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }
}

