# === file: services/attachment.go ===
package attachment

import (
	"net/http"

	repo_model "gitea.dev/models/repo"
	"gitea.dev/modules/storage"
	"gitea.dev/services/context"
)

// ResolveAndStream loads an attachment by the client-supplied UUID and
// streams it only after a centralized, unconditional authorization check:
// the owning repository is resolved from the attachment row itself and the
// requester must hold read permission on that repo (CWE-639 fixed).
func ResolveAndStream(ctx *context.Context, uuid string) {
	attach, err := repo_model.GetAttachmentByUUID(ctx, uuid)
	if err != nil {
		ctx.HTTPError(http.StatusNotFound)
		return
	}

	// Defense (CWE-639) step 1: resolve the owning repository from the
	// attachment row itself; an orphaned row (repo gone) is never disclosed.
	repo, err := repo_model.GetRepositoryByID(ctx, attach.RepoID)
	if err != nil {
		ctx.HTTPError(http.StatusNotFound)
		return
	}

	// Defense (CWE-639) step 2: unconditional permission check. It runs for
	// every row (legacy or not) and every caller; the old legacyCutoff and
	// nil-ctx.Repo bypasses no longer exist. A nil ctx.Doer (anonymous)
	// only yields anonymous permissions, so private-repo rows stay hidden.
	perm, err := repo_model.GetUserRepoPermission(ctx, repo, ctx.Doer)
	if err != nil {
		ctx.ServerError("GetUserRepoPermission", err)
		return
	}
	if !perm.CanRead(repo_model.UnitTypeCode) {
		ctx.HTTPError(http.StatusNotFound)
		return
	}

	blob := &storage.AttachmentBlob{
		UUID:         attach.UUID,
		Name:         attach.Name,
		RelativePath: attach.RelativePath(),
	}
	if err := storage.StreamAttachment(ctx.Resp, ctx.Req, blob); err != nil {
		ctx.ServerError("StreamAttachment", err)
	}
}
# === file: modules/storage/attachment.go ===
package storage

import (
	"net/http"

	"gitea.dev/modules/httplib"
)

// AttachmentBlob is the minimal descriptor handed to the object store.
type AttachmentBlob struct {
	UUID         string
	Name         string
	RelativePath string
}

// StreamAttachment opens the stored object and writes its bytes to the
// response. It performs no authorization itself; whatever blob reaches
// this function is disclosed verbatim (SINK).
func StreamAttachment(resp http.ResponseWriter, req *http.Request, blob *AttachmentBlob) error {
	fr, err := Attachments.Open(blob.RelativePath)
	if err != nil {
		return err
	}
	defer fr.Close()
	httplib.ServeUserContentByFile(req, resp, fr, httplib.ServeHeaderOptions{Filename: blob.Name})
	return nil
}

