namespace App\Service;

use InvalidArgumentException;

final class MetadataSanitizer
{
    // 修复: 由单趟删除后放行改为命中即整体拒绝;
    // 拒绝式检查不改写原始字符串, <!DOCT<!DOCTYPEYPE 之类的嵌套重组绕过在结构上失效;
    // 本层为纵深防御第一层, 主防线是 DOMDocumentFactory 中基于解析器配置的集中式加固。
    public function assertNoDtd(string $xml): string
    {
        if (preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F]/', $xml) === 1) {
            throw new InvalidArgumentException('Control characters are not allowed in XML input');
        }
        if (preg_match('/<\s*!(?:DOCTYPE|ENTITY)/i', $xml) === 1) {
            throw new InvalidArgumentException('DTD or entity declarations are not allowed');
        }
        return $xml;
    }
}
