"""集中式授权模块：调用方认证 + 目标令牌归属校验，全部入口强制经过。"""

from .token_store import TOKEN_STORE


class AuthorizationError(Exception):
    """调用方未认证，或对目标令牌不具备操作权限。"""


async def authenticate_caller(request) -> str:
    """从 Authorization: Bearer 头验证调用方自身凭证，返回其 client_id。"""
    auth_header = request.headers.get("authorization", "")
    if not auth_header.startswith("Bearer "):
        raise AuthorizationError("missing caller credentials")
    caller_token = auth_header[len("Bearer "):].strip()
    caller_record = await TOKEN_STORE.authenticate(caller_token)
    if not caller_record:
        raise AuthorizationError("unknown caller credentials")
    return caller_record["client_id"]


async def authorize_token_access(caller_client_id: str, target_token: str):
    """归属校验：目标令牌必须存在且属于该调用方，否则返回 None 统一拒绝。"""
    record = await TOKEN_STORE.lookup(target_token)
    if not record or record["client_id"] != caller_client_id:
        return None
    return record

