import re

from .authz import AuthorizationError, authorize_token_access
from .token_store import TOKEN_STORE


class TokenIntrospectionService:
    """中间层：格式净化 + 集中式授权校验（调用方身份 + 目标令牌归属）。"""

    _TOKEN_RE = re.compile(r"^[A-Za-z0-9_\-]{8,64}$")

    async def introspect(self, raw_token: str, caller_client_id: str):
        # 防御：格式白名单仅作输入规范化，真正的防线是下方归属校验
        cleaned = raw_token.strip()
        if not self._TOKEN_RE.match(cleaned):
            return {"active": False}
        # 防御：不再直接 lookup，改经授权层校验调用方与令牌的归属关系
        record = await authorize_token_access(caller_client_id, cleaned)
        if not record:
            return {"active": False}
        return {
            "active": True,
            "client_id": record["client_id"],
            "scope": record["scope"],
            "aud": record["resource"],
        }

    async def revoke(self, raw_token: str, caller_client_id: str):
        cleaned = raw_token.strip()  # 仅字符串清理，授权由下一行集中校验
        # 防御：仅令牌属主可撤销，未通过归属校验则抛出授权异常
        record = await authorize_token_access(caller_client_id, cleaned)
        if not record:
            raise AuthorizationError("target token not owned by caller")
        await TOKEN_STORE.delete(cleaned)
        return {"revoked": True}

# === file: app/token_store.py ===
"""全局内存令牌库，以原始令牌字符串为主键。"""

TOKENS = {
    "tok-alice-0001": {"client_id": "client-A", "scope": "mcp:read", "resource": "rs://alpha"},
    "tok-bob-0002": {"client_id": "client-B", "scope": "mcp:write", "resource": "rs://beta"},
}


class TokenStore:
    async def lookup(self, token_str: str):
        # SINK: 现仅可由 authz.authorize_token_access 在归属校验通过后触达
        return TOKENS.get(token_str)

    async def authenticate(self, token_str: str):
        # 防御：调用方自身凭证验证专用入口（调用方本就持有该令牌，非越权读）
        return TOKENS.get(token_str)

    async def delete(self, token_str: str):
        # 防御：到达此处前必须已通过 authz 层归属校验（services.py 强制）
        return TOKENS.pop(token_str, None)


TOKEN_STORE = TokenStore()

