<?php
declare(strict_types=1);

namespace App\Service;

use DOMDocument;
use DOMNode;
use RuntimeException;

final class MetadataSanitizer
{
    // 旧版 removeDtd 用单趟 str_replace 改写输入, 可被 <!DOCT<!DOCTYPEYPE 嵌套重组绕过;
    // 字符串级改写本身不可靠, 现改为解析后结构白名单校验: 只放行元数据合法的节点形态,
    // 出现 DOCTYPE(DTD) 或实体引用节点即整体拒绝, 不再尝试改写输入。
    public function assertNoDtd(DOMDocument $dom): void
    {
        if ($dom->doctype !== null) {
            throw new RuntimeException('DTD declarations are not allowed in metadata');
        }

        $stack = [$dom->documentElement];
        while ($stack !== []) {
            /** @var DOMNode $node */
            $node = array_pop($stack);
            if ($node->nodeType === XML_ENTITY_REF_NODE) {
                throw new RuntimeException('Entity references are not allowed in metadata');
            }
            foreach ($node->childNodes as $child) {
                $stack[] = $child;
            }
        }
    }
}
