package attachment

import (
	"net/http"

	repo_model "gitea.dev/models/repo"
	"gitea.dev/modules/storage"
	"gitea.dev/services/context"
)

// ResolveAndStream loads an attachment by the client-supplied UUID and streams
// it only after centralized authorization succeeds: the owning repository is
// resolved from the attachment row itself and the caller must hold read
// permission on that repository (CWE-639 fix). No legacy cutoff and no
// reliance on ctx.Repo remain.
func ResolveAndStream(ctx *context.Context, uuid string) {
	attach, err := repo_model.GetAttachmentByUUID(ctx, uuid)
	if err != nil {
		ctx.HTTPError(http.StatusNotFound)
		return
	}

	// FIX (CWE-639): unconditional, fail-closed authorization for every row.
	// The owning repo comes from the attachment record, not from the request,
	// so legacy rows and repo-less contexts pass through the same gate.
	repo, err := repo_model.GetRepositoryByID(ctx, attach.RepoID)
	if err != nil {
		ctx.HTTPError(http.StatusNotFound)
		return
	}
	perm, err := repo_model.GetUserRepoPermission(ctx, repo, ctx.Doer)
	if err != nil {
		ctx.ServerError("GetUserRepoPermission", err)
		return
	}
	if !perm.CanRead(repo_model.UnitTypeAttachment) {
		ctx.HTTPError(http.StatusNotFound)
		return
	}

	blob := &storage.AttachmentBlob{
		UUID:         attach.UUID,
		Name:         attach.Name,
		RelativePath: attach.RelativePath(),
	}
	if err := storage.StreamAttachment(ctx.Resp, ctx.Req, blob); err != nil {
		ctx.ServerError("StreamAttachment", err)
	}
}
