package com.ctrip.framework.apollo.portal.service;

import com.ctrip.framework.apollo.common.dto.ReleaseDTO;
import com.ctrip.framework.apollo.portal.component.AdminServiceClient;
import com.ctrip.framework.apollo.portal.component.PermissionValidator;
import com.ctrip.framework.apollo.portal.entity.vo.ReleaseCompareResult;
import com.ctrip.framework.apollo.portal.environment.Env;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;

@Service
public class ReleaseService {

  private final AdminServiceClient adminServiceClient;
  private final PermissionValidator permissionValidator;

  public ReleaseService(AdminServiceClient adminServiceClient,
                        PermissionValidator permissionValidator) {
    this.adminServiceClient = adminServiceClient;
    this.permissionValidator = permissionValidator;
  }

  public ReleaseDTO loadRelease(String env, long releaseId) {
    Env environment = Env.valueOf(env); // 仅规范化环境名, 资源归属由 checkReleaseAccess 集中校验
    ReleaseDTO release = adminServiceClient.findReleaseById(environment, releaseId);
    checkReleaseAccess(release);
    return release;
  }

  public ReleaseCompareResult compareReleases(String env, long baseId, long toCompareId) {
    Env environment = Env.valueOf(env);
    checkReleaseAccess(adminServiceClient.findReleaseById(environment, baseId));
    checkReleaseAccess(adminServiceClient.findReleaseById(environment, toCompareId));
    return adminServiceClient.compare(environment, baseId, toCompareId);
  }

  /**
   * 集中式授权校验: 资源归属只信任 release 自身的 appId/namespaceName,
   * 与当前登录用户的权限做匹配, 未授权一律拒绝, 防止遍历 releaseId 越权读取配置。
   */
  private void checkReleaseAccess(ReleaseDTO release) {
    if (release == null) {
      return;
    }
    if (!permissionValidator.userHasNamespacePermission(release.getAppId(), release.getNamespaceName())) {
      throw new AccessDeniedException("Access denied for release " + release.getId());
    }
  }
}

