package com.ctrip.framework.apollo.portal.component;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.AnonymousAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;

/**
 * 集中式授权校验组件: 判定当前登录用户是否拥有指定资源归属 (appId + namespaceName) 的访问权限。
 * 授权依据只来自服务端权限库与资源自身归属属性, 不接受请求中任何用户可控标识。
 */
@Component
public class PermissionValidator {

  private final JdbcTemplate jdbcTemplate;

  public PermissionValidator(JdbcTemplate jdbcTemplate) {
    this.jdbcTemplate = jdbcTemplate;
  }

  /**
   * 校验当前登录用户是否对指定命名空间拥有任一授权角色。
   */
  public boolean userHasNamespacePermission(String appId, String namespaceName) {
    String username = currentUsername();
    if (username == null) {
      return false;
    }
    // 参数化查询: 授权比对值一律不拼接进 SQL
    String sql = "SELECT COUNT(*) FROM Role r JOIN UserRole ur ON r.Id = ur.RoleId "
        + "WHERE r.AppId = ? AND r.TargetId = ? AND ur.UserId = ?";
    Integer matched = jdbcTemplate.queryForObject(sql, Integer.class, appId, namespaceName, username);
    return matched != null && matched > 0;
  }

  private String currentUsername() {
    Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
    if (authentication == null || authentication instanceof AnonymousAuthenticationToken
        || !authentication.isAuthenticated()) {
      return null;
    }
    return authentication.getName();
  }
}

