package routes

import (
	"errors"
	"net/http"

	"gogs.io/gogs/internal/lfsx"
)

// SessionStore validates opaque session tokens and returns the
// authenticated principal; it is the only trusted source of identity.
type SessionStore interface {
	Validate(token string) (int64, error)
}

// MountLFS exposes GET /lfs/objects/{oid}. Access requires a valid,
// server-validated session AND an explicit object-level ACL allow;
// cookie presence alone is never sufficient.
func MountLFS(mux *http.ServeMux, store lfsx.Storager, sessions SessionStore, authz lfsx.Authorizer) {
	mux.Handle("GET /lfs/objects/{oid}", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		c, err := r.Cookie("session")
		if err != nil || c.Value == "" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		principal, err := sessions.Validate(c.Value) // DEFENSE: validate token server-side, derive trusted principal
		if err != nil {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		oid := lfsx.OID(r.PathValue("oid")) // SOURCE: attacker-controlled
		err = lfsx.ServeObject(store, oid, principal, authz, w)
		switch {
		case err == nil:
			return
		case errors.Is(err, lfsx.ErrInvalidOID):
			http.Error(w, "invalid oid", http.StatusBadRequest)
		case errors.Is(err, lfsx.ErrAccessDenied), errors.Is(err, lfsx.ErrObjectNotExist):
			// DEFENSE: denied and missing both map to 404 so object existence is not revealed.
			http.Error(w, "not found", http.StatusNotFound)
		default:
			http.Error(w, "internal error", http.StatusInternalServerError)
		}
	}))
}

