package lfsx

import "io"

// Authorizer is the centralized, deny-by-default authorization point:
// every object read must be answered by an explicit allow for the
// (principal, oid) pair; a well-formed OID alone grants nothing.
type Authorizer interface {
	CanReadObject(principal int64, oid OID) bool
}

// ACLIndex is the persistent ownership/ACL mapping for LFS objects.
type ACLIndex interface {
	// CanRead reports whether principal is explicitly allowed to read oid.
	CanRead(principal int64, oid OID) bool
}

// ACLAuthorizer is the deny-by-default Authorizer backed by an ACLIndex.
// It replaces hash-as-capability: knowing or guessing an OID grants
// nothing unless the ACL explicitly allows this principal.
type ACLAuthorizer struct {
	acl ACLIndex
}

func NewACLAuthorizer(acl ACLIndex) *ACLAuthorizer {
	return &ACLAuthorizer{acl: acl}
}

// CanReadObject denies by default and allows only on an explicit ACL hit.
func (a *ACLAuthorizer) CanReadObject(principal int64, oid OID) bool {
	if a == nil || a.acl == nil {
		return false
	}
	return a.acl.CanRead(principal, oid)
}

// ServeObject shape-checks the OID, then verifies object-level
// authorization for the authenticated principal before delegating.
func ServeObject(s Storager, oid OID, principal int64, authz Authorizer, w io.Writer) error {
	if !ValidOIDShape(oid) {
		return ErrInvalidOID
	}
	if authz == nil || !authz.CanReadObject(principal, oid) { // DEFENSE: centralized ownership/ACL check
		return ErrAccessDenied
	}
	return s.Download(oid, w) // unmodified oid flows onward, now behind authorization
}

// ValidOIDShape reports whether oid looks like a sha256 hex digest.
func ValidOIDShape(oid OID) bool {
	if len(oid) != 64 {
		return false
	}
	for i := 0; i < len(oid); i++ {
		c := oid[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

