package playlist

import (
	"encoding/base64"
)

// DecodeID 只负责把客户端提交的 id 还原为存储相对路径；
// 不再使用可绕过的黑名单替换，路径边界由 Store.resolve 的包含性校验兜底，
// 归属校验由 Store.Read / Store.Delete 的集中式授权完成。
func DecodeID(id string) (string, error) {
	path, err := base64.URLEncoding.DecodeString(id)
	if err != nil {
		return "", err
	}
	return string(path), nil
}

# === file: playlist/store.go ===
package playlist

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
)

type Playlist struct {
	UserID   uint
	Name     string
	Comment  string
	IsPublic bool
	Items    []string
}

type Store struct{ BaseDir string }

var (
	// ErrOutsideStore 表示解析结果越出存储根目录，被路径边界白名单拒绝。
	ErrOutsideStore = errors.New("path resolves outside playlist store")
	// ErrNotOwner 表示请求者不是该播放列表的属主，被集中式授权拒绝。
	ErrNotOwner = errors.New("requester does not own this playlist")
)

// resolve 把相对路径并入 BaseDir 后用 filepath.Rel 做包含性校验：
// 只有仍落在存储根目录内部的结果才放行，取代原先对 .. 的黑名单替换。
func (s *Store) resolve(p string) (string, error) {
	joined := filepath.Join(s.BaseDir, p)
	rel, err := filepath.Rel(s.BaseDir, joined)
	if err != nil {
		return "", ErrOutsideStore
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", ErrOutsideStore
	}
	return joined, nil
}

// readResolved 统一完成路径解析与文件读取，供 Read 与 Delete 两个入口共用。
func (s *Store) readResolved(p string) (*Playlist, string, error) {
	full, err := s.resolve(p)
	if err != nil {
		return nil, "", err
	}
	raw, err := os.ReadFile(full)
	if err != nil {
		return nil, "", err
	}
	var pl Playlist
	if err := json.Unmarshal(raw, &pl); err != nil {
		return nil, "", err
	}
	return &pl, full, nil
}

// Read 在返回数据前执行集中式授权：仅属主可读，公开播放列表对所有人可读。
func (s *Store) Read(requesterID uint, p string) (*Playlist, error) {
	pl, _, err := s.readResolved(p)
	if err != nil {
		return nil, err
	}
	if pl.UserID != requesterID && !pl.IsPublic {
		return nil, ErrNotOwner
	}
	return pl, nil
}

// Delete 在删除前执行集中式授权：仅属主可删，公开标记不授予删除权。
func (s *Store) Delete(requesterID uint, p string) error {
	pl, full, err := s.readResolved(p)
	if err != nil {
		return err
	}
	if pl.UserID != requesterID {
		return ErrNotOwner
	}
	return os.Remove(full)
}

