import re

from app import viewers

# 白名单精确允许集：标题仅允许字母、数字、空格、下划线、连字符与点，长度受限
_TITLE_ALLOWED = re.compile(r'^[A-Za-z0-9 _.-]{0,64}$')


class GalleryService:
    '''中间层：对 title 做白名单精确校验，路径校验下沉到 sink 层统一执行'''

    def __init__(self):
        self.pending = ''

    def stage(self, name):
        self.pending = name

    def display(self, path=None, title=None):
        target = path or self.pending
        if title is not None and not _TITLE_ALLOWED.fullmatch(title):
            return 0
        v = viewers.pick_viewer()
        return v.show_image(target, title=title)

