import os
import subprocess

GALLERY_ROOT = os.path.realpath(os.path.join(os.path.dirname(__file__), 'gallery'))


class Viewer:
    def get_command(self, file, **options):
        raise NotImplementedError

    def _safe_path(self, path):
        # 白名单式路径约束：realpath 归一化后必须仍位于图库根目录内
        real = os.path.realpath(path)
        if os.path.commonpath([GALLERY_ROOT, real]) != GALLERY_ROOT:
            raise ValueError('path outside gallery root')
        return real

    def show_image(self, image, **options):
        return self.show_file(image, **options)

    def show_file(self, path, **options):
        safe = self._safe_path(path)
        if not os.path.exists(safe):
            raise FileNotFoundError
        # 修复 CWE-78：参数列表形式 + shell=False，元字符不再经 shell 解释
        subprocess.run(self.get_command(safe, **options), shell=False, check=False)
        return 1


class DisplayViewer(Viewer):
    def get_command(self, file, title=None, **options):
        command = ['display']
        if title:
            command += ['-title', title]
        return command + [file]


def pick_viewer():
    return DisplayViewer()

