// src/security/shell_guard.js
/**
 * Centralized allow-list validation for user supplied CLI options.
 * The old escape/quote composition was removed: values are never
 * sanitized by stripping characters, they must match an exact
 * allow-set or the call is rejected outright.
 */

// Exact allow-set for the --mode option.
const ALLOWED_MODES = new Set(['full', 'quick', 'deep']);

// Allow-list of characters permitted inside a --target value.
const SAFE_TARGET_CHARS = new Set(
  'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-/'
);

export function validateMode(mode) {
  if (!ALLOWED_MODES.has(mode)) {
    throw new Error('mode not allowed');
  }
  return mode;
}

export function validateTarget(target) {
  if (target === '.') {
    return target;
  }
  if (target.length === 0 || target.startsWith('-')) {
    throw new Error('target not allowed');
  }
  for (const ch of target) {
    if (!SAFE_TARGET_CHARS.has(ch)) {
      throw new Error('target not allowed');
    }
  }
  return target;
}
