// src/service/runner.js
import { execFile } from 'child_process';
import { validateMode, validateTarget } from '../security/shell_guard.js';

/**
 * Run the bundled CLI tool with user supplied options.
 * Arguments are validated against centralized allow-lists and passed as
 * an argv array to execFile, so no shell is ever spawned and user data
 * can never be interpreted as shell syntax.
 */
export async function runTool(mode, target) {
  const safeMode = validateMode(mode);
  const safeTarget = validateTarget(target);
  return new Promise((resolve, reject) => {
    execFile(
      'cli-tool',
      ['--mode', safeMode, '--target', safeTarget],
      { shell: false },
      (err, stdout, stderr) => {
        if (err) {
          reject(err);
        } else {
          resolve(stdout || stderr);
        }
      }
    );
  });
}

