const path = require('path')
const fs = require('fs')
const { isWin } = require('../../common/runtime-constants')
const { run, runWinCmd } = require('../../common/shell-exec')

// Centralized allow-list jail: every tainted path must resolve inside one of
// these roots before any operation runs; replaces the old blacklist clean()
const ALLOWED_ROOTS = [
  path.resolve(__dirname, '..', '..', 'workspace')
]

// Single choke point shared by rmrfPath/movePath/folderSize and therefore by
// all three HTTP routes and any direct caller of this service
function assertAllowedPath (p) {
  if (typeof p !== 'string' || p.length === 0 || p.includes('\0')) {
    throw new Error('rejected: path must be a non-empty string without NUL bytes')
  }
  let real
  try {
    real = fs.realpathSync(path.resolve(p)) // collapses .. segments and symlinks
  } catch (e) {
    real = path.resolve(p) // target may not exist yet (e.g. move destination)
  }
  const norm = s => (isWin ? s.toLowerCase() : s)
  const inside = ALLOWED_ROOTS.some(root => {
    const r = norm(root)
    const t = norm(real)
    return t === r || t.startsWith(r + path.sep)
  })
  if (!inside) {
    throw new Error('rejected: path resolves outside the allowed workspace roots')
  }
  return real
}

async function rmrfPath (localFolderPath) {
  const safe = assertAllowedPath(localFolderPath)
  if (isWin) {
    return runWinCmd(
      'Remove-Item -LiteralPath $env:FS_TARGET -Force -Recurse -ErrorAction SilentlyContinue',
      { FS_TARGET: safe }
    )
  }
  return run('rm', ['-rf', '--', safe]) // argv array: never parsed by a shell
}

async function movePath (from, to) {
  const safeFrom = assertAllowedPath(from)
  const safeTo = assertAllowedPath(to)
  if (isWin) {
    return runWinCmd(
      'Move-Item -LiteralPath $env:FS_FROM -Destination $env:FS_TO -Force',
      { FS_FROM: safeFrom, FS_TO: safeTo }
    )
  }
  return run('mv', ['--', safeFrom, safeTo])
}

async function folderSize (folderPath) {
  const safe = assertAllowedPath(folderPath)
  if (isWin) {
    return runWinCmd(
      'Get-ChildItem -LiteralPath $env:FS_TARGET -Recurse -Force | Measure-Object Length -Sum',
      { FS_TARGET: safe }
    )
  }
  const [sizeOut, listOut] = await Promise.all([
    run('du', ['-sh', '--', safe]),
    run('find', [safe, '-type', 'f'])
  ])
  const fileCount = listOut.split('\n').filter(l => l.length > 0).length
  return `${sizeOut.trim()}\n${fileCount}`
}

module.exports = { rmrfPath, movePath, folderSize }

# === file: common/shell-exec.js ===
const { promisify } = require('util')
const { execFile } = require('child_process')

const execFileAsync = promisify(execFile)

// Shell-free execution: program and arguments travel as separate argv
// entries, so no shell ever interprets quotes, semicolons, pipes, &&,
// $(), backticks or newlines contained in caller-supplied data
const run = (file, args) => {
  return execFileAsync(file, args, { shell: false, maxBuffer: 64 * 1024 * 1024 })
    .then(r => r.stdout.toString())
}

// powershell.exe is spawned directly with a fixed literal script; tainted
// data reaches PowerShell only through the process environment, which is
// expanded as pure data ($env:FS_TARGET etc.) and never parsed as code
const runWinCmd = (script, envVars) => {
  return execFileAsync(
    'powershell.exe',
    ['-NoProfile', '-NonInteractive', '-Command', script],
    { shell: false, maxBuffer: 64 * 1024 * 1024, env: { ...process.env, ...(envVars || {}) } }
  ).then(r => r.stdout.toString())
}

module.exports = { run, runWinCmd }

