# === file: internal/fileutil/sanitize.go ===
package fileutil

import (
	"errors"
	"path/filepath"
	"strings"
)

// DEFENSE: exact whitelist allow-set for object keys. Only lowercase
// letters, digits, '_', '-' and '.' are accepted; the key must be a single
// clean path element, must not start with a dot and must not contain '..'.
// Invalid input is rejected outright, never silently rewritten.
var ErrUnsafeKey = errors.New("object key rejected by whitelist")

const maxFilenameLength = 200

// Safe validates the request key against the allow-set and returns it
// unchanged on success; it no longer strips characters or truncates.
func Safe(filename string) (string, error) {
	if filename == "" || len(filename) > maxFilenameLength {
		return "", ErrUnsafeKey
	}
	if filename != filepath.Base(filename) { // rejects separators and absolute paths
		return "", ErrUnsafeKey
	}
	if strings.Contains(filename, "..") { // rejects dot-dot traversal sequences
		return "", ErrUnsafeKey
	}
	if filename[0] == '.' { // rejects dotfiles and all-dot names such as '..'
		return "", ErrUnsafeKey
	}
	for _, r := range filename {
		switch {
		case r >= 'a' && r <= 'z':
		case r >= '0' && r <= '9':
		case r == '_' || r == '-' || r == '.':
		default:
			return "", ErrUnsafeKey
		}
	}
	return filename, nil
}

// HasPrefix enforces path boundaries and is now called on every resolved path.
func HasPrefix(p, prefix string) bool {
	return p == prefix || strings.HasPrefix(p, filepath.Clean(prefix)+string(filepath.Separator))
}

