package store

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"example.com/app/internal/fileutil"
)

const UploadRoot = "/var/lib/app/uploads"

// ErrOutsideRoot is returned when a resolved path escapes the upload root.
var ErrOutsideRoot = errors.New("resolved path escapes upload root")

// Load resolves a user key against the shared root and reads that file.
func Load(name string) ([]byte, error) {
	p, err := resolve(UploadRoot, name, 0)
	if err != nil {
		return nil, err
	}
	// DEFENSE: centralized boundary check at the sink, covering every caller
	// of store.Load including direct constructions outside the HTTP layer.
	if !fileutil.HasPrefix(filepath.Clean(p), UploadRoot) {
		return nil, ErrOutsideRoot
	}
	root, err := filepath.EvalSymlinks(UploadRoot)
	if err != nil {
		return nil, err
	}
	real, err := filepath.EvalSymlinks(p)
	if err != nil {
		return nil, err
	}
	if !fileutil.HasPrefix(real, root) {
		return nil, ErrOutsideRoot
	}
	return os.ReadFile(real) // SINK, reached only for paths inside UploadRoot
}

func resolve(base, filename string, count uint) (string, error) {
	var suffix string
	if count > 0 {
		suffix = fmt.Sprintf(" (%d)", count)
	}
	path := base + suffix
	if filename != "" {
		noExt := strings.TrimSuffix(filename, filepath.Ext(filename))
		path = filepath.Join(base, noExt+suffix+filepath.Ext(filename))
	}
	_, err := os.Stat(path)
	if os.IsNotExist(err) {
		return path, nil
	}
	if err != nil {
		return "", err
	}
	return resolve(base, filename, count+1)
}

