package tools

import (
	"errors"
	"regexp"
	"strings"
)

// allowCommands is an exact-match whitelist of read-only utilities that
// cannot spawn child processes, so no allowlisted entry can be turned
// into a shell or a downloader by any argument combination.
var allowCommands = map[string]struct{}{
	"cat": {}, "date": {}, "echo": {}, "grep": {}, "head": {},
	"ls": {}, "pwd": {}, "tail": {}, "uname": {}, "wc": {}, "whoami": {},
}

// safeToken is a positive charset allowlist (not a denylist): every
// token must consist solely of benign characters, so separators,
// expansions and quotes cannot survive even if a shell is reintroduced.
var safeToken = regexp.MustCompile(`^[A-Za-z0-9_@%+=:,./-]+$`)

// ParseCommand splits the raw string WITHOUT shell semantics: plain
// whitespace tokenization, so quote-splitting tricks like r''m are
// impossible by construction.
func ParseCommand(command string) (string, []string, error) {
	fields := strings.Fields(command)
	if len(fields) == 0 {
		return "", nil, errors.New("empty command")
	}
	bin := strings.ToLower(fields[0])
	if _, ok := allowCommands[bin]; !ok { // exact whitelist lookup
		return "", nil, errors.New("command not allowed: " + bin)
	}
	for _, tok := range fields {
		if !safeToken.MatchString(tok) {
			return "", nil, errors.New("illegal character in argument")
		}
	}
	return bin, fields[1:], nil
}

# === file: internal/tools/executor.go ===
package tools

import (
	"bytes"
	"context"
	"os/exec"
)

// RunShell keeps its historical name so both HTTP entries stay untouched,
// but it no longer spawns any shell: the allowlisted binary is executed
// directly with a verbatim argument vector. The guard is centralized here
// so every caller, including the legacy debug route, is protected.
func RunShell(ctx context.Context, cwd, command string) (string, error) {
	bin, args, err := ParseCommand(command) // CENTRAL GUARD: whitelist gate
	if err != nil {
		return "", err
	}
	path, err := exec.LookPath(bin)
	if err != nil {
		return "", err
	}
	cmd := exec.CommandContext(ctx, path, args...) // no shell: args stay literal
	if cwd != "" {
		cmd.Dir = cwd
	}
	var out bytes.Buffer
	cmd.Stdout = &out
	err = cmd.Run()
	return out.String(), err
}

