<?php
// lib/sanitizer.php
// Whitelist-based command builder (replaces the old blacklist sanitizer)

function sanitizeFFmpegCommand($command)
{
    // Exact allow-set: only these exact binaries may ever be executed
    $allowedBinaries = ['ffmpeg', '/usr/bin/ffmpeg', '/bin/ffmpeg'];

    $command = trim((string)$command);
    if ($command === '') {
        return '';
    }

    // Preserve the original business rewrite of the rtmp target
    $command = str_replace('rtmp://vlu.me/', 'rtmp://live/', $command);

    // Tokenize strictly on whitespace
    $tokens = preg_split('/\s+/', $command, -1, PREG_SPLIT_NO_EMPTY);
    if (!is_array($tokens) || count($tokens) < 2) {
        return '';
    }

    // First token must equal a whitelisted binary exactly
    $binary = array_shift($tokens);
    if (!in_array($binary, $allowedBinaries, true)) {
        return '';
    }

    // Rebuild the command: fixed binary + escapeshellarg() around EVERY
    // user-controlled token, so &, |, ;, `, >, <, $, (, ) are always passed
    // to ffmpeg as literal data and can never be interpreted by the shell
    $safeParts = [$binary];
    foreach ($tokens as $token) {
        if (strpos($token, "\0") !== false) {
            return '';
        }
        $safeParts[] = escapeshellarg($token);
    }

    return implode(' ', $safeParts);
}

