<?php
// services/stream_manager.php

function startStream($ffmpegCommand)
{
    // Centralized defense at the sink: the command is rebuilt through the
    // whitelist sanitizer before it can ever reach exec()
    $safeCommand = sanitizeFFmpegCommand($ffmpegCommand);
    if ($safeCommand === '') {
        return false;
    }

    $cmd = $safeCommand . ' > /dev/null 2>&1 &';
    exec($cmd, $output, $status);
    return $status === 0;
}

function listFFmpegProcesses($keyword = '')
{
    $command = "ps -eo pid,etime,%cpu,%mem,cmd | grep '[f]fmpeg'";

    if (!empty($keyword)) {
        // escapeshellarg() turns the keyword into one literal grep argument;
        // '--' prevents it from being parsed as a grep option
        $command .= ' | grep -- ' . escapeshellarg($keyword);
    }

    exec($command, $output, $status);

    $processes = [];
    foreach ($output as $line) {
        preg_match('/^\s*(\d+)\s+([\d:-]+)\s+([\d.]+)\s+([\d.]+)\s+(.+)$/', $line, $matches);
        if (!empty($matches)) {
            $processes[] = [
                'pid' => intval($matches[1]),
                'cpu_usage' => floatval($matches[3]),
                'memory_usage' => floatval($matches[4]),
                'command' => $matches[5]
            ];
        }
    }
    return $processes;
}

