import os
import subprocess


class Viewer:
    def get_command(self, file, **options):
        raise NotImplementedError

    def show_image(self, image, **options):
        return self.show_file(image, **options)

    def show_file(self, path, **options):
        if not os.path.exists(path):
            raise FileNotFoundError
        # 防御点（sink 层）：abspath 规范化保证文件参数不以 - 开头，防参数注入
        argv = self.get_command(os.path.abspath(path), **options)
        # 以 argv 列表执行并禁用 shell，元字符不再被 shell 解释
        subprocess.run(argv, shell=False)
        return 1


class DisplayViewer(Viewer):
    def get_command(self, file, title=None, **options):
        # 防御点（构造层）：返回参数列表，用户数据始终是独立 argv 元素
        argv = ['display']
        if title:
            argv += ['-title', title]
        argv.append(file)
        return argv


def pick_viewer():
    return DisplayViewer()

