<?php
namespace App\Support;

/**
 * Lightweight guard applied before invoking VCS tools.
 */
final class PathFilter
{
    /**
     * Strict allow-list: only letters, digits, dot, underscore,
     * dash and slash are accepted; traversal segments are rejected.
     */
    private const ALLOWED = '/^[A-Za-z0-9._\-\/]+$/';

    public static function clean(string $path): string
    {
        if (preg_match(self::ALLOWED, $path) !== 1) {
            throw new \InvalidArgumentException('illegal characters in path');
        }
        $path = ltrim($path, '/');
        foreach (explode('/', $path) as $segment) {
            if ($segment === '..') {
                throw new \InvalidArgumentException('path traversal rejected');
            }
        }
        return $path;
    }
}

