<?php
namespace App\Reports;

/**
 * Produces git blame output for one tracked file.
 */
class Gitblame
{
    public function generate(string $filename): array
    {
        return $this->getBlameContent($filename);
    }

    protected function getBlameContent(string $filename): array
    {
        $root = realpath(getcwd());
        if ($root === false) {
            return ['ERROR: blame command failed'];
        }
        $absolute = $root . DIRECTORY_SEPARATOR . ltrim($filename, '/\\');
        $real = realpath($absolute);
        if ($real === false || strpos($real, $root . DIRECTORY_SEPARATOR) !== 0) {
            return ['ERROR: file outside repository root'];
        }
        $relative = ltrim(substr($real, strlen($root)), '/\\');
        $command = 'git blame --date=short -- ' . escapeshellarg($relative) . ' 2>&1';
        $handle  = popen($command, 'r');
        if ($handle === false) {
            return ['ERROR: blame command failed'];
        }
        $raw = stream_get_contents($handle);
        pclose($handle);

        return explode("\n", $raw);
    }
}

