// Pass-through service layer between the HTTP route and the view.
const FILES = {
  'annual-report': { title: 'Annual Report', extension: 'pdf' },
  'brand-guide': { title: 'Brand Guide', extension: 'pdf' }
};

// Whitelist gate: a slug is accepted only when it is an exact own key of
// the FILES allow-set above; every other value collapses to the
// server-controlled constant UNKNOWN_NAME, so raw user input is never
// echoed into the view model. This exact allow-set replaces the old
// script-tag stripping blacklist, which attribute payloads bypassed.
const UNKNOWN_NAME = 'unknown-file';

function buildFileViewModel(slug) {
  const requested = String(slug == null ? '' : slug);
  const isWhitelisted = Object.prototype.hasOwnProperty.call(FILES, requested);
  const doc = isWhitelisted ? FILES[requested] : null;
  return {
    // only a whitelisted name or the constant can reach the download page
    requestedName: isWhitelisted ? requested : UNKNOWN_NAME,
    title: doc ? doc.title : '',
    extension: doc ? doc.extension : 'pdf'
  };
}

module.exports = { buildFileViewModel };

