// Interstitial download page. Every interpolated value passes through
// escapeHtml, a deterministic HTML entity encoder covering all five
// HTML metacharacters, before being concatenated into the markup.
// This is canonical output encoding, not an attack-detection blacklist.
function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderDownloadPage(res, model) {
  const href = `/uploads/${model.requestedName}.${model.extension}`;
  const html = [
    '<!doctype html><html><head><title>Download</title></head><body>',
    `<h1>${escapeHtml(model.title || model.requestedName)}</h1>`,
    `<p>You asked for: ${escapeHtml(model.requestedName)}</p>`,
    `<a id="dl" href="${escapeHtml(href)}">Download file</a>`,
    '</body></html>'
  ].join('');
  res.status(model.title ? 200 : 404).type('html').send(html);
}

module.exports = { renderDownloadPage };

