<?php
// lib/sanitizer.php
// Whitelist-based validator for ffmpeg commands (replaces the bypassable blacklist)

function sanitizeFFmpegCommand($command)
{
    // Exact allowlist of the binary: full equality match, never a prefix match
    $allowedBinaries = ['ffmpeg', '/usr/bin/ffmpeg', '/bin/ffmpeg'];

    // Per-argument allowlist: only URL/path/filter-safe characters are allowed,
    // every shell metacharacter (; | & $ > < ` ( ) { } ' " \ and whitespace) is absent by construction
    $safeTokenPattern = '/^[A-Za-z0-9_\-.,:\/=@%]+$/';

    // Preserve original business rule: rewrite the internal push URL
    $command = str_replace('rtmp://vlu.me/', 'rtmp://live/', $command);

    // Split strictly on whitespace so newline/tab cannot splice commands
    $tokens = preg_split('/\s+/', trim($command), -1, PREG_SPLIT_NO_EMPTY);
    if (empty($tokens)) {
        return '';
    }

    // The first token must equal one of the allowlisted binaries
    $binary = array_shift($tokens);
    if (!in_array($binary, $allowedBinaries, true)) {
        return '';
    }

    // Every remaining token must fully match the allowlist; any violation rejects the whole command
    foreach ($tokens as $token) {
        if (!preg_match($safeTokenPattern, $token)) {
            return '';
        }
    }

