    $binary = array_shift($tokens);
    if (!in_array($binary, $allowedBinaries, true)) {
        return '';
    }

    foreach ($tokens as $token) {
        if (!preg_match($safeTokenPattern, $token)) {
            return '';
        }
    }

    return $binary . ' ' . implode(' ', $tokens);
}
```

