package tools

import (
	"errors"
	"strings"
)

// allowTools is the EXACT allow set of executables this API may run.
// Nothing outside the set can be executed; there is no deny list to evade.
var allowTools = map[string]struct{}{
	"ls":   {},
	"cat":  {},
	"grep": {},
	"wc":   {},
	"head": {},
	"tail": {},
	"pwd":  {},
	"echo": {},
}

// Allow is the single centralized gate for every execution path:
// the program name must exactly match the allow set, and no argument
// may start with - (blocks option injection such as find -exec style).
func Allow(program string, args []string) error {
	name := strings.ToLower(strings.TrimSpace(program))
	if name == "" {
		return errors.New("empty program name")
	}
	if _, ok := allowTools[name]; !ok {
		return errors.New("program not in allow list")
	}
	for _, a := range args {
		if strings.HasPrefix(a, "-") {
			return errors.New("option arguments are not permitted")
		}
	}
	return nil
}

# === file: internal/tools/executor.go ===
package tools

import (
	"bytes"
	"context"
	"os/exec"
	"strings"
)

// RunShell executes ONLY a whitelisted program with plain arguments.
// No shell is ever spawned (sh -c / powershell -Command removed), so
// metacharacters like ; | && $() ` cannot be interpreted (CWE-78 fix).
func RunShell(ctx context.Context, cwd, program string, args ...string) (string, error) {
	name := strings.ToLower(strings.TrimSpace(program))
	if err := Allow(name, args); err != nil { // centralized allow-list gate
		return "", err
	}
	cmd := exec.CommandContext(ctx, name, args...) // SINK: direct exec, argument vector, no shell
	if cwd != "" {
		cmd.Dir = cwd
	}
	var out bytes.Buffer
	cmd.Stdout = &out
	err := cmd.Run()
	return out.String(), err
}

