'use strict';

const { detachNodeFromParent } = require('../lib/xast.js');

exports.name = 'sanitizeSvg';
exports.type = 'visitor';
exports.active = true;
exports.description = 'whitelist-based SVG sanitizer: keep only known-safe elements and attributes';

// 元素白名单: 仅保留纯绘图类元素, script/foreignObject/iframe/animate/a/style 等一律不在表内
const ELEMENT_ALLOWLIST = new Set([
  'svg', 'g', 'defs', 'symbol', 'title', 'desc',
  'path', 'rect', 'circle', 'ellipse', 'line', 'polyline', 'polygon',
  'text', 'tspan', 'textPath',
  'linearGradient', 'radialGradient', 'stop', 'pattern',
  'clipPath', 'mask', 'marker',
  'image', 'use',
  'filter', 'feBlend', 'feColorMatrix', 'feComposite', 'feGaussianBlur',
]);

// 属性白名单: 仅保留展示/几何类属性, 不含 style, 不含任何事件处理器
const ATTR_ALLOWLIST = new Set([
  'id', 'class', 'width', 'height', 'x', 'y', 'x1', 'y1', 'x2', 'y2',
  'cx', 'cy', 'r', 'rx', 'ry', 'd', 'points', 'transform',
  'viewBox', 'preserveAspectRatio', 'xmlns', 'xmlns:xlink', 'version',
  'fill', 'fill-opacity', 'fill-rule', 'stroke', 'stroke-width',
  'stroke-opacity', 'stroke-linecap', 'stroke-linejoin', 'stroke-dasharray',
  'opacity', 'offset', 'stop-color', 'stop-opacity',
  'gradientUnits', 'gradientTransform', 'spreadMethod',
  'clip-path', 'clip-rule', 'mask', 'filter', 'patternUnits', 'patternContentUnits',
  'marker-start', 'marker-mid', 'marker-end', 'orient', 'markerUnits',
  'markerWidth', 'markerHeight', 'refX', 'refY', 'path',
  'font-family', 'font-size', 'font-weight', 'font-style',
  'text-anchor', 'dominant-baseline', 'dx', 'dy', 'rotate', 'textLength', 'lengthAdjust',
]);

// URI 类属性: 值必须通过协议白名单校验
const URI_ATTRS = new Set(['href', 'xlink:href']);
const SAFE_DATA_IMAGE_PATTERN = /^data:image\/(png|jpeg|jpg|gif|webp);base64,[a-z0-9+/=]+$/i;

function isSafeUri(value) {
  // 去除空白与控制字符, 防 java\tscript: 之类的解析差异绕过
  const v = String(value).replace(/[\s\x00-\x1f\x7f]/g, '');
  if (SAFE_DATA_IMAGE_PATTERN.test(v)) return true;
  if (/^https?:\/\//i.test(v)) return true;
  if (v.startsWith('#')) return true;
  if (v.startsWith('/')) return !v.startsWith('//');
  // 其余视为相对路径, 只要携带 scheme(如 javascript:)即拒绝
  return !/^[a-z][a-z0-9+.\-]*:/i.test(v);
}

exports.fn = () => {
  return {
    element: {
      enter: (node, parentNode) => {
        // 非元素节点(文本/CDATA/无名字根)直接放行, 文本交由序列化器转义
        if (typeof node.name !== 'string') return;
        // 元素不在白名单 -> 连同子树整体移除; 根级未知元素则清空属性与子树
        if (!ELEMENT_ALLOWLIST.has(node.name)) {
          if (parentNode) {
            detachNodeFromParent(node, parentNode);
          } else {
            node.attributes = {};
            node.children = [];
          }
          return;
        }
        // 属性过滤: 事件处理器显式拒绝, 其余按白名单放行, URI 属性再做协议校验
        const safeAttrs = {};
        for (const [name, value] of Object.entries(node.attributes || {})) {
          const lowerName = name.toLowerCase();
          if (lowerName.startsWith('on')) continue;
          if (URI_ATTRS.has(lowerName)) {
            const v = String(value).trim();
            const ok = node.name === 'use' ? v.startsWith('#') : isSafeUri(v);
            if (!ok) continue;
          } else if (!ATTR_ALLOWLIST.has(name)) {
            continue;
          }
          safeAttrs[name] = value;
        }
        node.attributes = safeAttrs;
      },
    },
  };
};

