# === file: marklet/parser.py ===
import re

DIRECTIVE_RE = re.compile(
    r'!!!\s+(?P<name>[A-Za-z_]\w*)'
    r'(?:\s+"(?P<title>[^"\n]*)")?'
    r'(?:\s+:class=(?P<cls>\S+))?'
)

# 白名单精确允许集：仅放行内置提示块类型，未知名称一律归化为 note
ALLOWED_ADMONITION_NAMES = frozenset({
    "note", "attention", "caution", "danger", "error", "hint", "important",
    "tip", "warning", "info", "seealso",
})

# class 属性白名单：完整锚定，仅允许 CSS 标识符字符，不匹配整体丢弃
_CLASS_RE = re.compile(r"[A-Za-z0-9_-]+")


def sanitize_class(cls):
    """白名单校验 class：不匹配则整体丢弃，绝不裁剪拼接。"""
    if cls and _CLASS_RE.fullmatch(cls):
        return cls
    return ""


def parse_admonition(markdown_text: str):
    """从原始 Markdown 提取第一个 !!! 提示块，生成渲染 token。"""
    m = DIRECTIVE_RE.search(markdown_text or "")
    if not m:
        return None
    name = m.group("name")
    if name.lower() not in ALLOWED_ADMONITION_NAMES:
        name = "note"
    title = m.group("title") or name.capitalize()
    cls = sanitize_class(m.group("cls") or "")
    return {
        "type": "admonition",
        "title": title,
        "attrs": {
            "name": name,
            "class": cls,
        },
    }


# === file: marklet/html_renderer.py ===
from markupsafe import escape


def render_admonition_title(text: str) -> str:
    """标题文本先经 HTML 实体集中转义，再拼入 <p> 标签内部。"""
    return '<p class="admonition-title">' + str(escape(text)) + "</p>\n"


def render_admonition(token: dict) -> str:
    attrs = token["attrs"]
    html = '<section class="admonition ' + str(escape(attrs["name"]))
    if attrs.get("class"):
        html += " " + str(escape(attrs["class"]))
    html += '">\n'
    html += render_admonition_title(token["title"])
    return html + "</section>\n"


def render_token(token) -> str:
    if isinstance(token, dict) and token.get("type") == "admonition":
        return render_admonition(token)
    return ""

