from typing import ClassVar, Literal, Tuple

_SPECIALS = {"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}

def escape_text(text: str) -> str:
    for ch, rep in _SPECIALS.items():
        text = text.replace(ch, rep)
    return text

# 修复：白名单精确允许集——仅放行安全协议，无协议前缀视为站内相对路径
SAFE_SCHEMES: Tuple[str, ...] = ("http", "https", "mailto")

def _extract_scheme(url: str) -> str:
    # 浏览器解析 URL 时会忽略制表/换行等控制字符，先剔除再判定，防止 java\tscript: 类绕过
    compact = "".join(ch for ch in url if ord(ch) > 0x20 and ord(ch) != 0x7F)
    idx = compact.find(":")
    if idx <= 0:
        return ""
    head = compact[:idx]
    if not head[0].isalpha():
        return ""
    if not all(ch.isalnum() or ch in "+-." for ch in head):
        return ""
    return head.lower()

class PageRenderer:
    NAME: ClassVar[Literal["html"]] = "html"

    def __init__(self) -> None:
        # 修复：移除 escape 开关与 allow_harmful_protocols 放行名单，防护不可被配置关闭
        pass

    def safe_url(self, url: str) -> str:
        # 修复：删除放行名单短路逻辑，改为白名单精确匹配，非白名单协议一律拒绝
        scheme = _extract_scheme(url)
        if scheme and scheme not in SAFE_SCHEMES:
            return "#harmful-link"
        return escape_text(url)

    def render_link(self, text: str, url: str) -> str:
        # 修复：text 先经 escape_text 再拼入标签体，杜绝标签体注入
        return '<a href="' + self.safe_url(url) + '">' + escape_text(text) + "</a>"

    def render_inline_html(self, html: str) -> str:
        # 修复：用户内容无条件转义后输出，删除 escape=False 的原始输出分支
        return escape_text(html)

