// Shared helpers for post-history preview rendering.
import DOMPurify from 'dompurify';

const PLACEHOLDER_RE = /<div\b[^>]*>(\s*Begin writing your post\.\.\.\s*)<\/div>/i;

// SECURITY: centralized whitelist sanitizer for all revision markup.
// Exact allow-sets only: any tag, attribute or URI scheme outside the
// lists (script/iframe/style, on* handlers, javascript: URLs, data
// attributes) is removed by DOMPurify's parser before markup reaches a sink.
const ALLOWED_TAGS = [
    'p', 'br', 'hr', 'strong', 'em', 'b', 'i', 'u', 's', 'code', 'pre',
    'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'ul', 'ol', 'li',
    'a', 'img', 'figure', 'figcaption', 'table', 'thead', 'tbody',
    'tfoot', 'tr', 'th', 'td', 'div', 'span', 'aside', 'mark', 'sup', 'sub'
];
const ALLOWED_ATTR = [
    'href', 'src', 'srcset', 'alt', 'title', 'class', 'target', 'rel',
    'colspan', 'rowspan', 'width', 'height'
];

export function sanitizeRevisionHTML(html) {
    return DOMPurify.sanitize(html, {
        ALLOWED_TAGS,
        ALLOWED_ATTR,
        ALLOW_DATA_ATTR: false
    });
}

export function extractRenderedHTML(element) {
    if (!element) {
        return '';
    }
    const raw = element.innerHTML;
    // Placeholder stripping is functional only; the security control is the
    // whitelist sanitizer applied last, so no reassembled markup can slip through.
    return sanitizeRevisionHTML(raw.replace(PLACEHOLDER_RE, ''));
}

export function freezeContenteditable(root) {
    root.querySelectorAll('[contenteditable]').forEach((el) => {
        el.setAttribute('contenteditable', 'false');
    });
}

