    public function findAll(SearchCriteria $criteria): array
    {
        $sql = 'SELECT * FROM ' . self::TABLE_NAME;
        $params = [];
        if ($criteria->searchTerm !== '') {
            // Defense: user input only ever reaches the SQL as a bound
            // parameter, never via string concatenation.
            $sql .= ' WHERE identifier LIKE ? OR label LIKE ?';
            $pattern = '%' . $criteria->searchTerm . '%';
            $params = [$pattern, $pattern];
        }
        if ($criteria->hasLimit()) {
            // Defense: LIMIT value is bound too; $criteria->limit is a
            // strictly typed int (readonly property plus (int) cast).
            $sql .= ' LIMIT ?';
            $params[] = $criteria->limit;
        }
        return $this->connection->fetchAllAssociative($sql, $params);
