'use strict';
// Serializer extracted from domino NodeUtils: node -> HTML fragment.
var HTML_NS = 'http://www.w3.org/1999/xhtml';

function escape(s) {
  return s.replace(/[&<>"'\u00A0]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;',
      '"': '&quot;', "'": '&#39;', '\u00A0': '&nbsp;' }[c];
  });
}

function escapeMatchingClosingTag(rawText, parentTag) {
  var closing = '</' + parentTag;
  if (!rawText.toLowerCase().includes(closing)) return rawText;
  return rawText.replace(new RegExp(closing, 'ig'), function (m) {
    return '&lt;' + m.slice(1);
  });
}

// kid: {nodeType, data}; parent: {nodeType, namespaceURI, tagName}
// FIX (CWE-79/CWE-116): encoding is now uniform and parent-independent.
// The hasRawContent table and the verbatim raw-text branch were removed:
// no parent choice (STYLE, SCRIPT, XMP, ...) can switch off escaping, and
// directly constructed calls all hit this single encoding path.
function serializeOne(kid, parent) {
  var s = '';
  switch (kid.nodeType) {
    case 3: // TEXT_NODE
    case 4: // CDATA_SECTION_NODE
      // The HTML tokenizer runs RAWTEXT inside style/script/... and never
      // decodes character references there, so entity-escaped data cannot
      // yield a literal '</style' or any live tag in the output document.
      s += escape(String(kid.data));
      break;
    case 8: // COMMENT_NODE
      var cdata = kid.data;
      // A leading '>' or '->' would close the comment abruptly ('<!-->',
      // '<!--->') and release the rest as live markup; pad it off.
      if (/^(>|->)/.test(cdata)) cdata = ' ' + cdata;
      s += '<!--' + cdata.replace(/(--\!?)>/g, '$1&gt;') + '-->';
      break;
    default:
      s += escape(String(kid.data));
  }
  return s;
}

module.exports = { serializeOne: serializeOne,
  escapeMatchingClosingTag: escapeMatchingClosingTag };

