'use strict';
// Output policy for HTML responses.
//
// FIX (CWE-79/CWE-184): the former blacklist sanitizer stripped only paired
// <script> blocks and javascript: URIs with two regexes, so a </style>
// breakout followed by <img src=x onerror=...> passed through untouched.
// Blacklist filtering is removed entirely: encoding is enforced where the
// HTML is built (render/serializer.js escapes every text node), and this
// module hardens the response itself with a whitelist Content-Security-
// Policy so that even a future encoding gap cannot execute script or fetch
// remote resources.

function sendHtml(res, html) {
  res.type('text/html; charset=utf-8');
  res.set('X-Content-Type-Options', 'nosniff');
  // Whitelist policy: no script execution, no remote loads; only the
  // document's own inline <style> block is allowed.
  res.set('Content-Security-Policy',
    "default-src 'none'; script-src 'none'; img-src 'none'; style-src 'unsafe-inline'");
  res.send(html);
}

module.exports = { sendHtml: sendHtml };

