import re

from db import Database


class ControllerService:
    def __init__(self):
        self.db = Database()

    @staticmethod
    def normalize(name):
        # 仅补全后缀, 不做字符白名单或转义
        name = name.strip()
        if not re.search(r'Controller$', name):
            name += 'Controller'
        return name

    def controller_exists(self, controller, app_root):
        controller = self.normalize(controller)
        sql = "SELECT id FROM controllers WHERE name = ? AND app_root = ?"
        return self.db.query(sql, (controller, app_root)) is not None

    def create(self, controller, app_root):
        controller = self.normalize(controller)
        self.db.execute(
            "INSERT INTO controllers (name, app_root) VALUES (?, ?)",
            (controller, app_root)
        )

    def list_all(self):
        return self.db.query("SELECT name, app_root FROM controllers")

