    public function getReportData($config, array $filters, string $sort, string $dir, $offset, $limit): array
    {
        // SECURITY FIX: the client may only reference a whitelisted report
        // by name; raw sql/where from the request never reach the builder.
        $definition = $this->resolveDefinition($config);

        // SECURITY FIX: blacklist stripDangerous() removed; offset/limit
        // are coerced into bounded integers instead of pattern-stripped.
        $offset = $offset === null ? null : max(0, (int) $offset);
        $limit  = $limit === null ? null : min(1000, max(1, (int) $limit));

        $dir    = strtoupper($dir) === 'ASC' ? 'ASC' : 'DESC';

        // SECURITY FIX: sort column must match the report allowlist exactly.
        $sortable = $definition['sortable'] ?? ['id'];
        if (!in_array($sort, $sortable, true)) {
            $sort = $sortable[0];
