    }

    private function resolveDefinition($config): array
    {
        $cfg  = (array) $config;
        $name = (string) ($cfg['name'] ?? '');
        if (!isset(SqlAdapter::REPORT_DEFINITIONS[$name])) {
            throw new \InvalidArgumentException('Unknown report definition');
        }
        return SqlAdapter::REPORT_DEFINITIONS[$name];
