<?php
namespace App\Tool\Adapter;

use Pimcore\Db;

class SqlAdapter
{
    /**
     * SECURITY FIX: server-side whitelist of report definitions. Query
     * bodies (sql/where) live only here and can never come from a client.
     */
    public const REPORT_DEFINITIONS = [
        'orders' => [
            'sql'      => 'SELECT o.id, o.orderNumber, o.total, o.orderDate FROM objects_orders o',
            'where'    => '',
            'sortable' => ['id', 'orderNumber', 'total', 'orderDate'],
        ],
        'customers' => [
            'sql'      => 'SELECT c.id, c.name, c.email FROM objects_customers c',
            'where'    => 'c.active = 1',
            'sortable' => ['id', 'name', 'email'],
        ],
    ];

    public function getData($config, array $filters, string $sort, string $dir, $offset, $limit): array
    {
        $db = Db::get();
        // SECURITY FIX: direction is re-whitelisted at the sink so that
        // direct adapter calls cannot bypass the service-level check.
        $dir = strtoupper($dir) === 'ASC' ? 'ASC' : 'DESC';
        $base = $this->getBaseQuery($config, $filters);
        $order = ' ORDER BY ' . $db->quoteIdentifier($sort) . ' ' . $dir;
        $sql = $base['data'] . $order;
        if ($offset !== null && $limit) {
            // SECURITY FIX: LIMIT/OFFSET are cast to integers at the sink;
            // no raw request string is ever concatenated into the SQL text.
            $sql .= ' LIMIT ' . (int) $offset . ',' . (int) $limit;
        }
        return [
            'data'  => $db->fetchAllAssociative($sql, $base['params']),
            'total' => $db->fetchOne($base['count'], $base['params']),
        ];
    }

    private function getBaseQuery($config, array $filters): array
    {
        $db = Db::get();
        $cfg = (array) $config;
        // SECURITY FIX: sink-side guard - even when the adapter is called
        // directly, the query body is taken from the whitelist, never from
        // client-supplied $cfg keys.
        $name = (string) ($cfg['name'] ?? '');
        if (!isset(self::REPORT_DEFINITIONS[$name])) {
            throw new \InvalidArgumentException('Unknown report definition');
        }
        $trusted = self::REPORT_DEFINITIONS[$name];
        $sql = "\n" . $trusted['sql'];
        if (!empty($trusted['where'])) {
            $sql .= "\n WHERE (" . $trusted['where'] . ')';
        }
        $condition = ['1 = 1'];
        $params = [];
        foreach ($filters as $filter) {
            if (!is_array($filter) || !isset($filter['property']) || !is_string($filter['property'])) {
                continue;
            }
            $condition[] = $db->quoteIdentifier($filter['property']) . ' = ?';
            $params[] = $filter['value'] ?? null;
        }
        $where = implode(' AND ', $condition);
        return [
            'data'  => 'SELECT * FROM (' . $sql . ') AS somerandxyz WHERE ' . $where,
            'count' => 'SELECT COUNT(*) FROM (' . $sql . ') AS somerandxyz WHERE ' . $where,
            'params' => $params,
        ];
    }
}

