package org.forgerock.oauth2.restlet;

import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.StringUtils;

/**
 * Builds the data model consumed by the consent page renderer.
 */
public class ConsentDataModelBuilder {

    // Input allowlist: only these characters may appear in a relative consent target.
    private static final String ALLOWED_TARGET_CHARS =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789/_-?.&=%~+";

    public Map<String, Object> build(String rawPath, String rawQuery) {
        String target = rawPath;
        if (!StringUtils.isBlank(rawQuery)) {
            target = target + "?" + rawQuery;
        }
        // Whitelist validation (input allowlist) replaces the bypassable script-tag blacklist.
        target = sanitizeTarget(target);

        Map<String, Object> data = new HashMap<>();
        data.put("target", target);
        data.put("display_name", "OpenAM Demo Client");
        return data;
    }

    private static String sanitizeTarget(String target) {
        if (StringUtils.isBlank(target) || target.charAt(0) != '/' || target.startsWith("//")) {
            return "/";
        }
        for (int i = 0; i < target.length(); i++) {
            if (ALLOWED_TARGET_CHARS.indexOf(target.charAt(i)) < 0) {
                return "/";
            }
        }
        return target;
    }
}
