<?php
declare(strict_types=1);

namespace App\Service;

use App\Model\CompositeIndexRepository;

class CompositeIndexService
{
    // 防御：标识符白名单精确允许集：仅字母/数字/下划线，首字符限字母或下划线，长度受限
    private const IDENTIFIER_PATTERN = '/^[A-Za-z_][A-Za-z0-9_]{0,63}$/';

    public function __construct(private CompositeIndexRepository $repository) {}

    public function applyCompositeIndices(string $table, string $type, array $compositeIndices): void
    {
        if (!in_array($type, ['query', 'localized_query'], true)) {
            throw new \InvalidArgumentException('unsupported index type');
        }

        // 防御：表名必须同时通过字符集白名单并命中数据库真实存在的表白名单
        if ($table === '' || !preg_match(self::IDENTIFIER_PATTERN, $table) || !$this->repository->tableExists($table)) {
            throw new \InvalidArgumentException('unknown table');
        }

        // 防御：读取真实表结构列名集合，作为列白名单
        $existingColumns = array_map('strtolower', $this->repository->getTableColumns($table));

        $normalized = [];
        foreach ($compositeIndices as $item) {
            $rawKey = (string) ($item['index_key'] ?? '');
            // 防御：索引名先过字符集白名单再统一加 c_ 前缀，杜绝反引号、括号、分号等元字符
            if ($rawKey === '' || !preg_match(self::IDENTIFIER_PATTERN, $rawKey)) {
                throw new \InvalidArgumentException('invalid index key');
            }
            $rawColumns = (string) ($item['index_columns'] ?? '');
            $validatedColumns = [];
            foreach (array_map('trim', explode(',', $rawColumns)) as $column) {
                // 防御：逐列做字符集白名单并核对真实列集合，空段直接拒绝
                if ($column === '' || !preg_match(self::IDENTIFIER_PATTERN, $column)
                    || !in_array(strtolower($column), $existingColumns, true)) {
                    throw new \InvalidArgumentException('invalid index column');
                }
                $validatedColumns[] = $column;
            }
            $normalized[] = [
                'index_key' => 'c_' . $rawKey,
                'index_columns' => implode(', ', $validatedColumns),
            ];
        }

        $this->repository->updateCompositeIndices($table, $normalized);
    }
}
