<?php
declare(strict_types=1);

namespace App\Model;

use Doctrine\DBAL\Connection;

class CompositeIndexRepository
{
    public function __construct(private Connection $db) {}

    // 防御：以数据库元数据生成表白名单，供服务层精确允许集校验
    public function tableExists(string $table): bool
    {
        return in_array($table, $this->db->createSchemaManager()->listTableNames(), true);
    }

    // 防御：返回指定表的真实列名集合，供服务层列白名单校验
    public function getTableColumns(string $table): array
    {
        return array_keys($this->db->createSchemaManager()->listTableColumns($table));
    }

    public function updateCompositeIndices(string $table, array $compositeIndices): void
    {
        $existing = $this->db->fetchAllAssociative(
            'SHOW INDEXES FROM ' . $this->db->quoteIdentifier($table) . " WHERE Key_Name LIKE 'c\\_%'"
        );
        $existingMap = [];
        foreach ($existing as $row) {
            $existingMap[$row['Key_name']] = $row['Column_name'];
        }
        foreach ($compositeIndices as $index) {
            $key = $index['index_key'];
            $columns = $index['index_columns'];
            if (isset($existingMap[$key]) && $existingMap[$key] === $columns) {
                continue;
            }
            // 防御：sink 处对表名、索引名、每个列名统一 quoteIdentifier 转义，并移除语句尾部分号
            $quotedColumns = implode(', ', array_map(
                fn (string $column): string => $this->db->quoteIdentifier(trim($column)),
                explode(',', $columns)
            ));
            $this->db->executeQuery(
                'ALTER TABLE ' . $this->db->quoteIdentifier($table)
                . ' ADD INDEX ' . $this->db->quoteIdentifier($key)
                . ' (' . $quotedColumns . ')'
            );
        }
    }
}

