import re

DIRECTIVE_RE = re.compile(
    r'!!!\s+(?P<name>[A-Za-z_]\w*)'
    r'(?:\s+"(?P<title>[^"\n]*)")?'
    r'(?:\s+:class=(?P<cls>\S+))?'
)

# 白名单精确允许集：仅允许内置提示块类型进入渲染链
ALLOWED_ADMONITION_NAMES = frozenset({
    "note", "attention", "caution", "danger", "error", "hint",
    "important", "tip", "warning", "admonition",
})

# class 白名单：整串必须仅由字母/数字/下划线/连字符组成
_CLASS_RE = re.compile(r"^[A-Za-z0-9_-]{1,64}$")


def _sanitize_class(cls):
    """class 值必须整体匹配白名单字符集，不匹配则整值丢弃。"""
    if cls and _CLASS_RE.match(cls):
        return cls
    return ""


def parse_admonition(markdown_text: str):
    """从原始 Markdown 提取第一个 !!! 提示块，生成渲染 token。"""
    m = DIRECTIVE_RE.search(markdown_text or "")
    if not m:
        return None
    name = m.group("name")
    if name.lower() not in ALLOWED_ADMONITION_NAMES:
        return None
    title = m.group("title") or name.capitalize()
