import ipaddress
import socket
from urllib.parse import urlparse

import requests

_session = requests.Session()

# GUARD: exact allow-set replaces the bypassable blacklist regex
_ALLOWED_SCHEMES = {"https"}


def _assert_public_ip(ip):
    # allow-list: only globally routable, non-multicast addresses may be contacted
    if not ip.is_global or ip.is_multicast:
        raise ValueError("host resolves to a non-public address")


def validate_webhook_url(url):
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    parsed = urlparse(url)
    if parsed.scheme not in _ALLOWED_SCHEMES:
        raise ValueError("scheme not allowed")
    if not parsed.hostname:
        raise ValueError("hostname required")
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    try:
        infos = socket.getaddrinfo(parsed.hostname, port, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        raise ValueError("cannot resolve host")
    for info in infos:
        _assert_public_ip(ipaddress.ip_address(info[4][0]))
    return url


def send_webhook(url, payload):
    # SINK: re-validate scheme and every resolved IP immediately before the outbound call
    validate_webhook_url(url)
    resp = _session.post(url, json=payload, timeout=5, allow_redirects=False)
    return resp.status_code

