from typing import ClassVar, Literal, Tuple

_SPECIALS = {"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}

def escape_text(text: str) -> str:
    for ch, rep in _SPECIALS.items():
        text = text.replace(ch, rep)
    return text

# 防御：白名单精确允许集，仅放行 http/https 绝对地址与站内相对路径
SAFE_URL_SCHEMES: Tuple[str, ...] = ("http://", "https://")

class PageRenderer:
    NAME: ClassVar[Literal["html"]] = "html"

    def __init__(self) -> None:
        # 修复：转义成为不可关闭的默认行为，外部无法再传入危险配置
        pass

    def safe_url(self, url: str) -> str:
        # 防御：先剥离首尾空白与制表/换行等控制字符，阻止 java\tscript: 类混淆写法，
        # 再按白名单精确允许集判定；javascript:/vbscript:/data:/file: 等一律降级
        candidate = "".join(ch for ch in url.strip() if ch not in "\t\n\r\f\v")
        lowered = candidate.lower()
        if lowered.startswith(SAFE_URL_SCHEMES):
            return escape_text(candidate)
        if candidate.startswith("/") and not candidate.startswith("//"):
            return escape_text(candidate)
        return "#harmful-link"

