# === file: src/phpMyFAQ/Setup/UrlConfigProvider.php ===
<?php
declare(strict_types=1);

namespace phpMyFAQ\Setup;

use phpMyFAQ\Core\Exception;

/**
 * Reads environment values submitted by the setup wizard form.
 */
final class UrlConfigProvider
{
    /**
     * Precise allow-set for an installation path: the value must start
     * with a leading slash and may only contain A-Z a-z 0-9 . _ ~ - /
     * Spaces, #, quotes, %, backslashes and every control character
     * (including CR and LF) are outside the set and get rejected.
     */
    private const SERVER_PATH_PATTERN = '#\A/[A-Za-z0-9._~\-/]*\z#';

    /** Source: raw installer POST value, fully attacker-controlled. */
    public static function getDefaultUrlFromRequest(): string
    {
        return isset($_POST['faqDefaultUrl']) ? (string) $_POST['faqDefaultUrl'] : 'http://localhost/faq/';
    }

    /** parse_url only parses; the extracted path is therefore forced through the central allow-list gate below. */
    public static function getServerPath(): string
    {
        $path = parse_url(self::getDefaultUrlFromRequest(), PHP_URL_PATH);
        $path = ($path === null || $path === false || $path === '') ? '/' : $path;

        return self::assertSafeServerPath($path);
    }

    /**
     * Central whitelist gate for every value that may reach the .htaccess
     * writer: anything outside the allow-set fails closed with an exception.
     */
    public static function assertSafeServerPath(string $path): string
    {
        if (preg_match(self::SERVER_PATH_PATTERN, $path) !== 1) {
            throw new Exception('Invalid install path: only A-Z a-z 0-9 dot underscore tilde hyphen and slash are allowed.');
        }

        foreach (explode('/', $path) as $segment) {
            if ($segment === '.' || $segment === '..') {
                throw new Exception('Relative path segments are not allowed in the install path.');
            }
        }

        return $path;
    }
}

