<?php
declare(strict_types=1);

namespace phpMyFAQ\Setup;

/**
 * Composes .htaccess directive argument values.
 * Both values are derived exclusively from
 * UrlConfigProvider::getServerPath(), which enforces the central
 * path allow-list, so no raw metacharacter can reach composition.
 */
final class HtaccessRuleComposer
{
    /** Returns the whitelist-validated install path unchanged. */
    public function rewriteBaseValue(): string
    {
        return UrlConfigProvider::getServerPath();
    }

    /** rtrim only strips trailing slashes and cannot reintroduce metacharacters into the validated path. */
    public function errorDocument404Value(): string
    {
        $path = rtrim(UrlConfigProvider::getServerPath(), '/');
        return $path . '/index.php?action=404';
    }
}

# === file: src/phpMyFAQ/Setup/EnvironmentConfigurator.php ===
<?php
declare(strict_types=1);

namespace phpMyFAQ\Setup;

use phpMyFAQ\Core\Exception;

final class EnvironmentConfigurator
{
    private HtaccessRuleComposer $composer;

    /**
     * Second, independent allow-set applied at the sink: a complete
     * directive argument must start with a slash and may only contain
     * A-Z a-z 0-9 . _ ~ - / ? = &. Newlines, spaces, #, quotes and
     * every other Apache metacharacter are outside this set.
     */
    private const DIRECTIVE_VALUE_PATTERN = '/\A\/[A-Za-z0-9._~\-\/?=&]*\z/';

    public function __construct(private string $htaccessPath)
    {
        $this->composer = new HtaccessRuleComposer();
    }

    public function adjustRewriteBaseHtaccess(): bool
    {
        if (!file_exists($this->htaccessPath)) {
            throw new Exception('The .htaccess file does not exist!');
        }

        $lines = file($this->htaccessPath, FILE_IGNORE_NEW_LINES) ?: [];
        $out = [];
        foreach ($lines as $line) {
            if (preg_match('/^\s*RewriteBase\b/i', $line)) {
                $out[] = 'RewriteBase ' . $this->validatedDirectiveValue($this->composer->rewriteBaseValue());
            } elseif (preg_match('/^\s*ErrorDocument\s+404\b/i', $line)) {
                $out[] = 'ErrorDocument 404 ' . $this->validatedDirectiveValue($this->composer->errorDocument404Value());
            } else {
                $out[] = $line;
            }
        }

        // Sink: only values that passed both allow-list gates reach the .htaccess writer
        return (bool) file_put_contents($this->htaccessPath, implode(PHP_EOL, $out));
    }

    /**
     * Sink gate: fail closed unless the composed value matches the
     * exact allow-set, so no extra directive can be smuggled in
     * through CR, LF, spaces or a # comment start.
     */
    private function validatedDirectiveValue(string $value): string
    {
        if (preg_match(self::DIRECTIVE_VALUE_PATTERN, $value) !== 1) {
            throw new Exception('Rejected unsafe htaccess directive value.');
        }

        return $value;
    }
}

