# === file: weed/remote_storage/config.go ===
package remote_storage

import (
	"encoding/json"
	"fmt"
	"net"
	"net/url"
	"strings"

	"github.com/seaweedfs/seaweedfs/weed/pb/remote_pb"
)

// endpointAllowlist is the exact, deployment-controlled set of remote
// storage endpoints this filer may talk to. Keys are canonical lowercased
// host:port pairs, populated from server-side configuration only; it can
// never be modified through the API-submitted RemoteConf.
var endpointAllowlist = map[string]bool{
	"s3.amazonaws.com:443":       true,
	"storage.googleapis.com:443": true,
}

// ValidateEndpoint is the single centralized gate for every user-supplied
// remote-storage endpoint: strict URL parsing, exact allowlist match on the
// canonical host:port, plus a DNS-resolution check refusing loopback,
// link-local and private targets.
func ValidateEndpoint(raw string) error {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return fmt.Errorf("endpoint must not be empty")
	}
	if !strings.Contains(trimmed, "://") {
		trimmed = "https://" + trimmed
	}
	u, err := url.Parse(trimmed)
	if err != nil {
		return fmt.Errorf("endpoint is not a valid URL: %w", err)
	}
	if u.Scheme != "https" {
		return fmt.Errorf("endpoint scheme must be https")
	}
	if u.User != nil {
		return fmt.Errorf("endpoint must not contain userinfo")
	}
	host := strings.ToLower(u.Hostname())
	port := u.Port()
	if port == "" {
		port = "443"
	}
	// Exact allowlist match: any host not explicitly configured here,
	// including 127.0.0.1, 169.254.169.254, [::1] and internal DNS names,
	// is rejected; no substring or regex heuristic is involved.
	if !endpointAllowlist[host+":"+port] {
		return fmt.Errorf("endpoint %s:%s is not in the allowed endpoint list", host, port)
	}
	// Defense in depth: resolve the allowlisted host and refuse any
	// loopback, link-local, private or unspecified address, which also
	// blocks DNS rebinding toward internal metadata services.
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("cannot resolve endpoint host %s: %w", host, err)
	}
	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsPrivate() || ip.IsUnspecified() {
			return fmt.Errorf("endpoint host %s resolves to forbidden address %s", host, ip)
		}
	}
	return nil
}

// ParseRemoteConf decodes a user-submitted remote-storage configuration
// arriving via the filer remote.configure admin API.
func ParseRemoteConf(raw []byte) (*remote_pb.RemoteConf, error) {
	conf := &remote_pb.RemoteConf{}
	if err := json.Unmarshal(raw, conf); err != nil {
		return nil, err
	}
	// Centralized allowlist validation replaces the naive substring guard.
	if err := ValidateEndpoint(conf.S3Endpoint); err != nil {
		return nil, err
	}
	return conf, nil
}

