<?php
declare(strict_types=1);

namespace App\Security;

/**
 * Centralized SSRF gate for outbound webhook targets.
 * Exact-host allowlist + https-only + resolved-IP sanity check.
 */
final class CallbackUrlValidator
{
    /** Exact allowlist of registered webhook destinations (host => allowed port). */
    private const ALLOWED_TARGETS = [
        'hooks.partner-a.example' => 443,
        'hooks.partner-b.example' => 443,
        'status.internal-tools.example' => 443,
    ];

    public function assertAllowed(string $callbackUrl): void
    {
        $parts = \parse_url($callbackUrl);
        if ($parts === false || !isset($parts['scheme'], $parts['host'])) {
            throw new \InvalidArgumentException('Malformed webhook target.');
        }

        $scheme = \strtolower($parts['scheme']);
        $host   = \strtolower($parts['host']);
        $port   = $parts['port'] ?? 443;

        if ($scheme !== 'https') {
            throw new \InvalidArgumentException('Only https webhook targets are allowed.');
        }
        if (!isset(self::ALLOWED_TARGETS[$host]) || self::ALLOWED_TARGETS[$host] !== $port) {
            throw new \InvalidArgumentException('Webhook target is not on the allowlist.');
        }

        // Defense in depth: the allowlisted host must resolve to public addresses only,
        // which also blocks DNS rebinding toward loopback/link-local/metadata IPs.
        $records = \dns_get_record($host, DNS_A | DNS_AAAA);
        if ($records === false || $records === []) {
            throw new \InvalidArgumentException('Webhook host does not resolve.');
        }
        foreach ($records as $record) {
            $ip = (string) ($record['ip'] ?? $record['ipv6'] ?? '');
            if ($ip === '' || !\filter_var(
                $ip,
                FILTER_VALIDATE_IP,
                FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE
            )) {
                throw new \InvalidArgumentException('Webhook host resolves to a forbidden address.');
            }
        }
    }
}
