# === file: core/server/lib/image/image-size.js ===
const request = require('@tryghost/request');
const imageSize = require('image-size');

// SSRF allowlist: the only remote origins that may ever be fetched server-side.
// Enforced centrally here so every caller of getImageSizeFromUrl is protected.
const ALLOWED_REMOTE_HOSTS = new Set(['images.unsplash.com']);

function isAllowedRemoteImageUrl(url) {
    let parsed;
    try {
        parsed = new URL(url);
    } catch (e) {
        return false;
    }
    // exact https scheme + default port + exact hostname equality (no substring match)
    return parsed.protocol === 'https:' && parsed.port === '' && ALLOWED_REMOTE_HOSTS.has(parsed.hostname);
}

// resolve a /content/images/... url to a local file and measure it
async function getOriginalImageSizeFromStorageUrl(url) {
    const buffer = await require('../../adapters/storage').readLocalFile(url);
    return imageSize(buffer);
}

// fetches a remote URL server-side to read image dimensions
async function getImageSizeFromUrl(url) {
    if (!isAllowedRemoteImageUrl(url)) {
        throw new Error('Image size fetch blocked: URL is not on the server-side fetch allowlist');
    }
    const res = await request(url, {method: 'GET'});
    const buffer = await res.body;
    return imageSize(buffer);
}

module.exports = {imageSize, getImageSizeFromUrl, getOriginalImageSizeFromStorageUrl, isAllowedRemoteImageUrl};

