package sanitize

import "fmt"

// 原黑名单式 SanitizeSQL/QuoteString 已整体删除:
// 拼接+转义无法可靠防注入, 防御职责移交驱动参数化与精确白名单。

// allowSort 为精确允许集: 键是 sort 唯一合法取值,
// 值是编译期写死的 SQL 片段, 不含任何运行时外部输入。
var allowSort = map[string]string{
	"name_asc":  "name ASC",
	"name_desc": "name DESC",
}

// SortClause 对外部输入做整键精确匹配, 命中才返回固定片段;
// 未命中(含空串与任意注入载荷)一律报错, 不做部分放行或二次清洗。
func SortClause(input string) (string, error) {
	if frag, ok := allowSort[input]; ok {
		return frag, nil
	}
	return "", fmt.Errorf("sort: disallowed value")
}

