package repo

import (
	"context"

	"example.com/app/internal/sanitize"

	"github.com/jackc/pgx/v5"
)

var conn *pgx.Conn // 由 main 包初始化

// FindUsers: name 改走 pgx 原生参数绑定($1), sort 先经精确白名单映射,
// 查询模板中不再存在任何未校验的外部输入。
func FindUsers(ctx context.Context, name, sort string) (string, error) {
	orderFrag, err := sanitize.SortClause(sort) // 防御点: sort 整键白名单精确匹配
	if err != nil {
		return "", err
	}
	q := "SELECT name FROM users WHERE name = $1 ORDER BY " + orderFrag + " LIMIT 20"
	rows, err := conn.Query(ctx, q, name) // SINK: SQL 执行; name 作为 $1 参数由驱动绑定
	if err != nil {
		return "", err
	}
	defer rows.Close()
	var out string
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			return "", err
		}
		out += n + "\n"
	}
	return out, rows.Err()
}

