<?php
namespace App\Security;

class UrlGuard
{
    // 防御核心：精确主机白名单，集中式出站授权，取代可绕过的主机黑名单
    private const ALLOWED_HOSTS = [
        'api.example.com',
        'data.example.com',
    ];

    public static function sanitize(string $url): string
    {
        $url = trim($url);
        $parsed = parse_url($url);
        if ($parsed === false || !isset($parsed['host'])) {
            return '';
        }
        $scheme = strtolower($parsed['scheme'] ?? '');
        if ($scheme !== 'http' && $scheme !== 'https') {
            return '';
        }
        $host = strtolower($parsed['host']);
        // 精确白名单匹配：未列出的主机一律拒绝（内网 IP、localhost 变体、十六进制/十进制 IP、IPv6 全部失效）
        if (!in_array($host, self::ALLOWED_HOSTS, true)) {
            return '';
        }
        // 纵深防御：DNS 解析复核，拒绝解析到私有/保留网段的白名单域名
        $ip = gethostbyname($host);
        if ($ip === $host || !filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE)) {
            return '';
        }
        // 拒绝显式端口，防止借白名单主机触碰同主机其他端口服务
        if (isset($parsed['port'])) {
            return '';
        }
        // 用已验证组件重建 URL，消除 parser 混淆与 userinfo/片段注入
        $path = ($parsed['path'] ?? '') . (isset($parsed['query']) ? '?' . $parsed['query'] : '');
        return $scheme . '://' . $host . $path;
    }
}
