<?php
namespace App\Service;

use App\Security\UrlGuard;

class WebServiceFetcher
{
    public function fetch(string $url): ?string
    {
        if ($url === '') {
            return null;
        }
        // SINK 前集中复核授权：覆盖绕过 Controller 直接调用 fetch 的替代通道
        if (UrlGuard::sanitize($url) !== $url) {
            return null;
        }
        $ctx = stream_context_create(['http' => [
            'user_agent' => 'Mozilla/5.0',
            'follow_location' => 0, // 禁止跟随重定向，阻断 30x 跳转内网的绕过
            'max_redirects' => 1,
            'timeout' => 5,
        ]]);
        $output = @file_get_contents($url, false, $ctx); // SINK: 服务端发起请求
        if ($output === false || mb_strlen($output) > 32767) {
            return null;
        }
        return $output;
    }
}

