import ipaddress
import socket
from urllib.parse import urlparse

from app.remote import fetch_schema

# 精确允许集：仅允许下列受信任主机提供 schema，取代原先可绕过的黑名单正则
_ALLOWED_SCHEMA_HOSTS = frozenset({
    'schemas.example.com',
    'specs.example.com',
    'json.schemastore.org',
})


def _validate_schema_url(schema_url: str) -> tuple:
    if not schema_url:
        raise ValueError('schema_url is required')
    if '://' not in schema_url:
        schema_url = 'https://' + schema_url
    parsed = urlparse(schema_url)
    if parsed.scheme != 'https':
        raise ValueError('only https is supported')
    host = (parsed.hostname or '').lower()
    if host not in _ALLOWED_SCHEMA_HOSTS:
        raise ValueError('schema host is not on the allowlist')
    try:
        addr_infos = socket.getaddrinfo(host, None)
    except socket.gaierror as exc:
        raise ValueError('cannot resolve schema host') from exc
    pinned_ips = []
    for info in addr_infos:
        ip = ipaddress.ip_address(info[4][0])
        if not ip.is_global or ip.is_multicast or ip.is_reserved:
            raise ValueError('schema host resolves to a non-public address')
        pinned_ips.append(str(ip))
    if not pinned_ips:
        raise ValueError('schema host resolved to no addresses')
    return schema_url, host, pinned_ips


def generate_models(schema_url: str, config: dict) -> str:
    schema_url, host, pinned_ips = _validate_schema_url(schema_url)
    config = dict(config)
    config['pinned_host'] = host
    config['pinned_ips'] = pinned_ips
    document = fetch_schema(schema_url, config)
    return _render(document, config)


def _render(document: str, config: dict) -> str:
    lines = ['# generated by internal codegen']
    lines.extend(document.splitlines())
    if config.get('allow_remote_refs'):
        lines.append('# remote refs resolved at request time')
    return '\n'.join(lines)

