import http.client
import ipaddress
import socket
import ssl
from urllib.parse import urlparse

DEFAULT_TIMEOUT = 10.0


def fetch_schema(url: str, config: dict) -> str:
    headers = dict(config.get('http_headers') or [])
    timeout = config.get('http_timeout') or DEFAULT_TIMEOUT
    host = config.get('pinned_host')
    pinned_ips = config.get('pinned_ips') or []
    if not host or not pinned_ips:
        raise ValueError('fetch_schema requires validated pinned_host and pinned_ips')
    parsed = urlparse(url)
    port = parsed.port or 443
    path = parsed.path or '/'
    if parsed.query:
        path = path + '?' + parsed.query
    safe_ips = []
    for ip_text in pinned_ips:
        ip = ipaddress.ip_address(ip_text)
        if not ip.is_global or ip.is_multicast or ip.is_reserved:
            raise ValueError('pinned IP is not a public address')
        safe_ips.append(str(ip))
    last_error = None
    for ip in safe_ips:
        try:
            return _fetch_via_ip(ip, port, host, path, headers, timeout)
        except (OSError, http.client.HTTPException) as exc:
            last_error = exc
    raise ValueError('all pinned addresses failed: %s' % last_error)


def _fetch_via_ip(ip: str, port: int, host: str, path: str, headers: dict, timeout: float) -> str:
    context = ssl.create_default_context()
    with socket.create_connection((ip, port), timeout=timeout) as raw_sock:
        with context.wrap_socket(raw_sock, server_hostname=host) as tls_sock:
            conn = http.client.HTTPSConnection(host, port, timeout=timeout, context=context)
            conn.sock = tls_sock
            try:
                conn.request('GET', path, headers=headers)
                resp = conn.getresponse()
                status = resp.status
                body = resp.read()
            finally:
                conn.close()
    if status // 100 != 2:
        raise ValueError('schema endpoint returned HTTP status %d' % status)
    return body.decode('utf-8', 'replace')

