// buildEndpointURL substitutes bidder params into the endpoint template and
// centrally validates the resolved URL before it can reach any HTTP sink.
func buildEndpointURL(endpoint *template.Template, params *openrtb_ext.ExtAcuityAds) (string, error) {
	endpointParams := macros.EndpointTemplateParams{Host: params.Host, AccountID: params.AccountID}
	resolved, err := macros.ResolveMacros(endpoint, endpointParams)
	if err != nil {
		return "", err
	}
	if err := validateEndpointURL(resolved); err != nil {
		return "", err
	}
	return resolved, nil
}

// validateEndpointURL parses rawURL with the same net/url semantics the HTTP
// client uses and applies the full endpoint policy to the parsed result.
func validateEndpointURL(rawURL string) error {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return &errortypes.BadInput{Message: "invalid endpoint url"}
	}
	return validateParsedEndpointURL(parsed)
}

// validateParsedEndpointURL enforces https, an exact host allowlist and rejects
// any host that resolves to loopback, private, link-local or unspecified IPs.
func validateParsedEndpointURL(parsed *url.URL) error {
	if parsed.Scheme != "https" {
		return &errortypes.BadInput{Message: "endpoint scheme must be https"}
	}
	if port := parsed.Port(); port != "" && port != "443" {
		return &errortypes.BadInput{Message: "endpoint port not allowed"}
	}
	host := strings.ToLower(parsed.Hostname())
	if _, ok := allowedHosts[host]; !ok {
		return &errortypes.BadInput{Message: "endpoint host not allowed"}
	}
	ips, err := net.LookupIP(host)
	if err != nil {
		return &errortypes.BadInput{Message: "endpoint host resolution failed"}
	}
	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
			return &errortypes.BadInput{Message: "endpoint host resolves to forbidden ip"}
		}
	}
	return nil
}
