import re

from app.storage import BackupStore


class BackupService:
    """Business layer: keeps backup metadata, delegates file operations."""

    _SAFE_SEGMENT = re.compile(r'[A-Za-z0-9][A-Za-z0-9._-]{0,254}')

    def __init__(self, base_dir: str) -> None:
        self.store = BackupStore(base_dir)
        self._meta: dict[str, str] = {}

    def register(self, backup_id: str, filename: str) -> None:
        # Whitelist allow-set: accept only one plain filename segment, no separators.
        if not self._is_safe_segment(backup_id) or not self._is_safe_segment(filename):
            raise ValueError('backup id and filename must be single safe path segments')
        self._meta[backup_id] = filename

    def delete(self, backup_id: str) -> None:
        if not self._is_safe_segment(backup_id):
            raise ValueError('backup id must be a single safe path segment')
        name = self._meta.get(backup_id, f'{backup_id}.tar')
        path = self.store.build_path(name)
        self.store.remove(path)

    @staticmethod
    def _is_safe_segment(segment: str) -> bool:
        return isinstance(segment, str) and BackupService._SAFE_SEGMENT.fullmatch(segment) is not None

