from pathlib import Path


class BackupStore:
    """Storage layer: all filesystem access for backups."""

    def __init__(self, base_dir: str) -> None:
        self.base = Path(base_dir).resolve()

    def build_path(self, name: str) -> Path:
        """Centralized containment check: canonicalize and confine to base dir."""
        candidate = (self.base / name).resolve()
        if self.base not in candidate.parents:
            raise ValueError('resolved path escapes the backup base directory')
        return candidate

    def remove(self, path: Path) -> None:
        """Delete a backup file from disk."""
        path.unlink(missing_ok=True)

