from urllib.parse import urlparse

from app.fetcher import get_body, join_url


def fetch_remote_schema(user_url: str, user_ref: str = ".") -> str:
    # a ref may only stay on the host supplied by the caller; absolute or
    # protocol-relative refs that silently repoint the host are rejected
    base_host = urlparse(user_url).hostname
    candidate = join_url(user_url, user_ref)
    if urlparse(candidate).hostname != base_host:
        raise ValueError("ref must not change the request host")
    # private-network enforcement lives only inside get_body and can no
    # longer be switched off by any caller
    return get_body(candidate)


# === file: app/fetcher.py ===
import ipaddress
import socket
from urllib.parse import urlparse

import httpx

DEFAULT_HTTP_TIMEOUT = 30.0
MAX_HTTP_REDIRECTS = 20


def join_url(url: str, ref: str = ".") -> str:
    # an absolute ref replaces scheme and host entirely; pure pass-through
    return str(httpx.URL(url).join(ref))


def _is_forbidden_ip(ip: ipaddress.IPv4Address | ipaddress.IPv6Address) -> bool:
    if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped is not None:
        ip = ip.ipv4_mapped
    return (
        ip.is_private
        or ip.is_loopback
        or ip.is_link_local
        or ip.is_reserved
        or ip.is_multicast
        or ip.is_unspecified
    )


def _validate_url_for_fetch(url: str) -> None:
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        raise ValueError("unsupported scheme")
    if parsed.hostname is None:
        raise ValueError("missing host")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("credentials in url are not allowed")
    try:
        infos = socket.getaddrinfo(parsed.hostname, None)
    except (socket.gaierror, UnicodeError) as exc:
        raise ValueError("cannot resolve host") from exc
    for info in infos:
        ip = ipaddress.ip_address(info[4][0])
        if _is_forbidden_ip(ip):
            raise ValueError("private or reserved address blocked")


def get_body(url: str) -> str:
    current_url = url
    for _ in range(MAX_HTTP_REDIRECTS + 1):
        _validate_url_for_fetch(current_url)
        response = httpx.get(current_url, follow_redirects=False, timeout=DEFAULT_HTTP_TIMEOUT)
        if response.status_code in (301, 302, 303, 307, 308):
            current_url = join_url(current_url, response.headers.get("location", ""))
            continue
        break
    return response.text

