import os

ALLOWED_INCLUDE_EXTENSIONS = (".md", ".markdown")  # 防御：白名单精确允许集，仅放行 Markdown 文档


def read_include(relpath: str, base_dir: str = "docs") -> str:
    base_abs = os.path.realpath(base_dir)  # 防御：解析 base_dir 真实路径作为信任边界
    dest = os.path.realpath(os.path.join(base_abs, relpath))  # 防御：解析最终真实路径，消解 ../ 绝对路径覆盖与符号链接
    try:
        contained = os.path.commonpath([base_abs, dest]) == base_abs  # 防御：包含性校验
    except ValueError:
        contained = False  # 跨盘符等无法比较的情形一律默认拒绝
    if not contained:
        raise FileNotFoundError(dest)
    if not relpath.lower().endswith(ALLOWED_INCLUDE_EXTENSIONS):  # 防御：扩展名精确允许集
        raise FileNotFoundError(relpath)
    if not os.path.isfile(dest):
        raise FileNotFoundError(dest)
    with open(dest, "rb") as f:  # sink：仅当路径收敛于 base_dir 且后缀受白名单约束才可达
        return f.read().decode("utf-8")

