const { isPrivateIp } = require('../utils/private-ip');

// FIXED: validation moved into the connection's own DNS lookup, so the
// address that is checked is the exact address the socket dials (no TOCTOU).
async function validatingLookup(hostname, options, callback) {
    const bareHost = hostname.replace(/^\[|\]$/g, ''); // strip IPv6 literal brackets
    const wantAll = Boolean(options && options.all);
    let addresses;
    try {
        addresses = await dnsPromises.lookup(bareHost, { all: true, verbatim: true });
    } catch (err) {
        callback(err);
        return;
    }
    if (!addresses || addresses.length === 0) {
        callback(new errors.InternalServerError({ message: 'Hostname resolved to no address', code: 'URL_PRIVATE_INVALID' }));
        return;
    }
    // Exact allowlist: only the configured site's own hostname skips the range check.
    let isSelfHost = false;
    try {
        isSelfHost = bareHost === new URL(config.get('url')).hostname;
    } catch (e) {
        isSelfHost = false;
    }
    if (!isSelfHost) {
        for (const entry of addresses) {
            if (isPrivateIp(entry.address)) {
                callback(new errors.InternalServerError({ message: 'URL resolves to a non-permitted private IP block', code: 'URL_PRIVATE_INVALID' }));
                return;
            }
        }
    }
    if (wantAll) {
        callback(null, addresses);
    } else {
        callback(null, addresses[0].address, addresses[0].family);
    }
}

const externalRequest = got.extend({
    timeout: 10000,
    lookup: validatingLookup
});

// SINK: outbound socket to the attacker-influenced host.
async function fetchRemote(url) {
    const response = await externalRequest(url, { responseType: 'json' });
    return response.body;
}

module.exports = { fetchRemote };
