package files

import (
	"path/filepath"
	"strings"
)

// Normalize 对用户路径做词法归一化：TrimSpace + filepath.Clean + 去前导分隔符。
// 注意：本函数仅做词法清理，不解析符号链接，不能单独充当 scope 边界防御；
// 真正的边界校验集中在 ReadScoped 内完成（EvalSymlinks + Rel 包含性检查）。
func Normalize(p string) string {
	p = strings.TrimSpace(p)
	p = filepath.Clean(p)
	return strings.TrimPrefix(p, string(filepath.Separator))
}
