package files

import (
	"os"
	"path/filepath"
	"strings"
)

// Scope 为共享根目录，由启动配置注入，例如 /srv/share
var Scope = "/srv/share"

// ReadScoped 读取 scope 内文件。
// 集中式防御（在唯一 sink 处实施，天然覆盖所有调用方与入口）：
// 先用 filepath.Join 做词法归一化折叠 ../ 序列；再用 filepath.EvalSymlinks
// 解析 scope 根与目标路径上的全部符号链接，阻断 scope 内软链指向外部的逃逸；
// 最后用 filepath.Rel 基于解析后的真实路径做层级包含校验，仅当目标未越过根
// （不为 ..、不以 ../ 开头、非绝对路径）时才放行，同时消除 /srv/share 与
// /srv/share2 这类字符串前缀混淆。
func ReadScoped(userPath string) ([]byte, error) {
	rel := Normalize(userPath)
	if rel == "" || rel == "." {
		return nil, os.ErrPermission
	}
	full := filepath.Join(Scope, rel)

	// scope 根自身也可能是符号链接，先解析其真实路径
	rootReal, err := filepath.EvalSymlinks(Scope)
	if err != nil {
		return nil, os.ErrPermission
	}
	// 逐级解析目标路径上的全部符号链接，得到不含软链的真实物理路径
	targetReal, err := filepath.EvalSymlinks(full)
	if err != nil {
		return nil, err
	}
	// 基于真实路径的包含性校验：这是唯一放行条件
	inside, err := filepath.Rel(rootReal, targetReal)
	if err != nil || inside == ".." || strings.HasPrefix(inside, ".."+string(os.PathSeparator)) || filepath.IsAbs(inside) {
		return nil, os.ErrPermission
	}
	return os.ReadFile(targetReal) // sink: 仅读取解析后确认仍在 scope 内的真实路径
}

